{
  "name": "Prüfungstrainer Pro",
  "description": "Eine Quiz-App, die KI verwendet, um Studenten bei der Vorbereitung auf ihre Abschlussprüfungen zu helfen, indem sie Übungsfragen zu jedem Thema generiert."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import { Question } from './types';
import TopicSelector from './components/TopicSelector';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Loader from './components/Loader';
import { generateQuiz } from './services/geminiService';

type GameState = 'config' | 'quiz' | 'results';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>('config');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleStartQuiz = useCallback(async (topic: string, numQuestions: number) => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedQuestions = await generateQuiz(topic, numQuestions);
      setQuestions(fetchedQuestions);
      setUserAnswers(new Array(fetchedQuestions.length).fill(null));
      setGameState('quiz');
    } catch (err) {
      setError('Fehler beim Generieren des Quiz. Bitte versuchen Sie es später erneut.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleAnswerSelect = (questionIndex: number, answerIndex: number) => {
    setUserAnswers(prev => {
      const newAnswers = [...prev];
      newAnswers[questionIndex] = answerIndex;
      return newAnswers;
    });
  };

  const handleSubmitQuiz = () => {
    setGameState('results');
  };

  const handleRestart = () => {
    setGameState('config');
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderContent = () => {
    if (isLoading) {
      return <Loader message="Quiz wird generiert... Bitte haben Sie einen Moment Geduld." />;
    }

    if (error) {
        return (
            <div className="text-center p-8 bg-white rounded-lg shadow-xl">
                <h2 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h2>
                <p className="text-slate-700 mb-6">{error}</p>
                <button
                    onClick={handleRestart}
                    className="bg-indigo-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-indigo-700 transition-colors duration-300"
                >
                    Zurück zum Start
                </button>
            </div>
        );
    }

    switch (gameState) {
      case 'quiz':
        return <Quiz 
          questions={questions} 
          userAnswers={userAnswers} 
          onAnswerSelect={handleAnswerSelect} 
          onSubmit={handleSubmitQuiz} 
        />;
      case 'results':
        return <Results 
          questions={questions} 
          userAnswers={userAnswers} 
          onRestart={handleRestart} 
        />;
      case 'config':
      default:
        return <TopicSelector onStartQuiz={handleStartQuiz} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 font-sans flex flex-col items-center justify-center p-4">
      <header className="w-full max-w-4xl mx-auto text-center mb-6">
        <h1 className="text-4xl md:text-5xl font-extrabold text-indigo-700">Prüfungstrainer Pro</h1>
        <p className="text-slate-600 mt-2 text-lg">Testen Sie Ihr Wissen mit KI-generierten Quizfragen.</p>
      </header>
      <main className="w-full max-w-4xl mx-auto">
        {renderContent()}
      </main>
       <footer className="w-full max-w-4xl mx-auto text-center mt-8 text-slate-500 text-sm">
        <p>Unterstützt durch die Gemini API</p>
      </footer>
    </div>
  );
};

export default App;

export interface Question {
  questionText: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Question } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const generateQuiz = async (topic: string, numQuestions: number): Promise<Question[]> => {
  const prompt = `Erstelle ein Multiple-Choice-Quiz auf Deutsch mit ${numQuestions} Fragen zum Thema "${topic}". Jede Frage sollte 4 Antwortmöglichkeiten haben, von denen nur eine richtig ist. Gib für jede Frage auch eine kurze Erklärung für die richtige Antwort. Die Fragen sollten für Studenten geeignet sein, die sich auf eine Abschlussprüfung vorbereiten. Die Schwierigkeit sollte angemessen sein. Gib die Antwort ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht. Füge keine Markdown-Formatierung oder andere Texte außerhalb des JSON-Objekts hinzu.`;

  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        questionText: { type: Type.STRING },
        options: {
          type: Type.ARRAY,
          items: { type: Type.STRING },
        },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING },
      },
      required: ['questionText', 'options', 'correctAnswerIndex', 'explanation'],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const jsonText = response.text.trim();
    const quizData = JSON.parse(jsonText);

    // Basic validation
    if (!Array.isArray(quizData) || quizData.length === 0) {
        throw new Error("API hat ein leeres oder ungültiges Quiz zurückgegeben.");
    }

    return quizData as Question[];
  } catch (error) {
    console.error("Fehler bei der Gemini-API-Anfrage:", error);
    throw new Error("Die Quizfragen konnten nicht generiert werden.");
  }
};

import React, { useState } from 'react';

interface TopicSelectorProps {
  onStartQuiz: (topic: string, numQuestions: number) => void;
}

const TopicSelector: React.FC<TopicSelectorProps> = ({ onStartQuiz }) => {
  const [topic, setTopic] = useState('');
  const [numQuestions, setNumQuestions] = useState(5);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (topic.trim()) {
      onStartQuiz(topic, numQuestions);
    }
  };

  return (
    <div className="bg-white p-8 rounded-xl shadow-lg animate-fade-in">
      <h2 className="text-2xl font-bold text-slate-800 text-center mb-6">Erstellen Sie Ihr Übungsquiz</h2>
      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="topic" className="block text-sm font-medium text-slate-700 mb-1">
            Thema
          </label>
          <input
            type="text"
            id="topic"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="z.B. Deutsche Geschichte, Quantenmechanik..."
            className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-shadow"
            required
          />
        </div>
        <div>
          <label htmlFor="numQuestions" className="block text-sm font-medium text-slate-700 mb-1">
            Anzahl der Fragen: <span className="font-bold text-indigo-600">{numQuestions}</span>
          </label>
          <input
            type="range"
            id="numQuestions"
            min="3"
            max="15"
            value={numQuestions}
            onChange={(e) => setNumQuestions(parseInt(e.target.value, 10))}
            className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
          />
        </div>
        <button
          type="submit"
          className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg hover:bg-indigo-700 focus:outline-none focus:ring-4 focus:ring-indigo-300 transition-all duration-300 transform hover:scale-105"
          disabled={!topic.trim()}
        >
          Quiz starten
        </button>
      </form>
    </div>
  );
};

export default TopicSelector;

import React, { useState } from 'react';
import { Question } from '../types';

interface QuizProps {
  questions: Question[];
  userAnswers: (number | null)[];
  onAnswerSelect: (questionIndex: number, answerIndex: number) => void;
  onSubmit: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, userAnswers, onAnswerSelect, onSubmit }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const currentQuestion = questions[currentQuestionIndex];
  const selectedAnswer = userAnswers[currentQuestionIndex];

  return (
    <div className="bg-white p-6 md:p-8 rounded-xl shadow-lg w-full">
      <div className="mb-6">
        <p className="text-sm text-slate-500">Frage {currentQuestionIndex + 1} von {questions.length}</p>
        <div className="w-full bg-slate-200 rounded-full h-2.5 mt-2">
          <div className="bg-indigo-600 h-2.5 rounded-full" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}></div>
        </div>
      </div>

      <h2 className="text-xl md:text-2xl font-bold text-slate-800 mb-6">{currentQuestion.questionText}</h2>

      <div className="space-y-4">
        {currentQuestion.options.map((option, index) => (
          <button
            key={index}
            onClick={() => onAnswerSelect(currentQuestionIndex, index)}
            className={`w-full text-left p-4 border-2 rounded-lg transition-all duration-200 text-slate-700
              ${selectedAnswer === index
                ? 'bg-indigo-100 border-indigo-500 ring-2 ring-indigo-300'
                : 'bg-white border-slate-300 hover:bg-slate-50 hover:border-indigo-400'
              }`}
          >
            <span className={`font-bold mr-3 ${selectedAnswer === index ? 'text-indigo-600' : 'text-slate-500'}`}>{String.fromCharCode(65 + index)}:</span> {option}
          </button>
        ))}
      </div>

      <div className="mt-8 flex justify-between items-center">
        <button
          onClick={handlePrev}
          disabled={currentQuestionIndex === 0}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-6 rounded-lg hover:bg-slate-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Zurück
        </button>
        {currentQuestionIndex < questions.length - 1 ? (
          <button
            onClick={handleNext}
            className="bg-indigo-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-indigo-700 transition-colors"
          >
            Weiter
          </button>
        ) : (
          <button
            onClick={onSubmit}
            className="bg-green-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-700 transition-colors"
          >
            Abschicken
          </button>
        )}
      </div>
    </div>
  );
};

export default Quiz;

import React from 'react';
import { Question } from '../types';
import CheckIcon from './icons/CheckIcon';
import XIcon from './icons/XIcon';

interface ResultsProps {
  questions: Question[];
  userAnswers: (number | null)[];
  onRestart: () => void;
}

const Results: React.FC<ResultsProps> = ({ questions, userAnswers, onRestart }) => {
  const score = userAnswers.reduce((acc, answer, index) => {
    return answer === questions[index].correctAnswerIndex ? acc + 1 : acc;
  }, 0);

  const scorePercentage = Math.round((score / questions.length) * 100);

  const getScoreColor = (percentage: number) => {
    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 50) return 'text-yellow-600';
    return 'text-red-600';
  };

  return (
    <div className="bg-white p-6 md:p-8 rounded-xl shadow-lg w-full">
      <div className="text-center border-b border-slate-200 pb-6 mb-6">
        <h2 className="text-3xl font-bold text-slate-800">Ergebnisse</h2>
        <p className="text-lg text-slate-600 mt-2">Dein Ergebnis</p>
        <p className={`text-6xl font-extrabold mt-4 ${getScoreColor(scorePercentage)}`}>
          {score} / {questions.length}
        </p>
        <p className="text-xl font-medium text-slate-500">({scorePercentage}%)</p>
      </div>

      <div className="space-y-6">
        {questions.map((question, index) => (
          <div key={index} className="border border-slate-200 p-4 rounded-lg">
            <h3 className="font-bold text-slate-800 flex items-start">
              <span className="mr-2">
                {userAnswers[index] === question.correctAnswerIndex 
                  ? <CheckIcon className="text-green-500 w-6 h-6 flex-shrink-0" /> 
                  : <XIcon className="text-red-500 w-6 h-6 flex-shrink-0" />}
              </span>
              {question.questionText}
            </h3>
            <div className="mt-4 space-y-2 pl-8">
              {question.options.map((option, optionIndex) => {
                const isCorrect = optionIndex === question.correctAnswerIndex;
                const isUserAnswer = optionIndex === userAnswers[index];

                let optionClasses = "p-2 rounded-md text-sm ";
                if(isCorrect) {
                  optionClasses += "bg-green-100 text-green-800 border-l-4 border-green-500";
                } else if (isUserAnswer && !isCorrect) {
                  optionClasses += "bg-red-100 text-red-800 border-l-4 border-red-500";
                } else {
                  optionClasses += "bg-slate-100 text-slate-700";
                }

                return (
                  <div key={optionIndex} className={optionClasses}>
                    {option}
                    {isCorrect && <span className="font-bold ml-2">(Richtige Antwort)</span>}
                    {isUserAnswer && !isCorrect && <span className="font-bold ml-2">(Deine Antwort)</span>}
                  </div>
                );
              })}
            </div>
            <div className="mt-4 p-3 bg-indigo-50 border-l-4 border-indigo-400 rounded-r-lg">
                <p className="text-sm font-semibold text-indigo-800">Erklärung:</p>
                <p className="text-sm text-indigo-700">{question.explanation}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="mt-8 text-center">
        <button
          onClick={onRestart}
          className="bg-indigo-600 text-white font-bold py-3 px-8 rounded-lg hover:bg-indigo-700 transition-all duration-300 transform hover:scale-105"
        >
          Nochmal versuchen
        </button>
      </div>
    </div>
  );
};

export default Results;

