                >
                    Zurück zum Start
                </button>
            </div>
        );
    }

    switch (gameState) {
      case 'quiz':
        return <Quiz 
          questions={questions} 
          userAnswers={userAnswers} 
          onAnswerSelect={handleAnswerSelect} 
          onSubmit={handleSubmitQuiz} 
        />;
      case 'results':
        return <Results 
          questions={questions} 
          userAnswers={userAnswers} 
          onRestart={handleRestart} 
        />;
      case 'config':
      default:
        return <TopicSelector onStartQuiz={handleStartQuiz} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 font-sans flex flex-col items-center justify-center p-4">
      <header className="w-full max-w-4xl mx-auto text-center mb-6">
        <h1 className="text-4xl md:text-5xl font-extrabold text-[#003366]">Prüfungstrainer Pro</h1>
        <p className="text-gray-600 mt-2 text-lg">Testen Sie Ihr Wissen mit KI-generierten Quizfragen.</p>
      </header>
      <main className="w-full max-w-4xl mx-auto">
        {renderContent()}
      </main>
       <footer className="w-full max-w-4xl mx-auto text-center mt-8 text-gray-500 text-sm">
        <p>Unterstützt durch die Gemini API</p>
      </footer>
    </div>
  );
};

export default App;

