import React, { useState } from 'react';
import { Question } from '../types';

interface QuizProps {
  questions: Question[];
  userAnswers: (number | null)[];
  onAnswerSelect: (questionIndex: number, answerIndex: number) => void;
  onSubmit: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, userAnswers, onAnswerSelect, onSubmit }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const currentQuestion = questions[currentQuestionIndex];
  const selectedAnswer = userAnswers[currentQuestionIndex];

  return (
    <div className="bg-white p-6 md:p-8 rounded-xl shadow-md w-full">
      <div className="mb-6">
        <p className="text-sm text-gray-500">Frage {currentQuestionIndex + 1} von {questions.length}</p>
        <div className="w-full bg-gray-200 rounded-full h-2.5 mt-2">
          <div className="bg-[#003366] h-2.5 rounded-full" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}></div>
        </div>
      </div>

      <h2 className="text-xl md:text-2xl font-bold text-gray-800 mb-6">{currentQuestion.questionText}</h2>

      <div className="space-y-4">
        {currentQuestion.options.map((option, index) => (
          <button
            key={index}
            onClick={() => onAnswerSelect(currentQuestionIndex, index)}
            className={`w-full text-left p-4 border-2 rounded-lg transition-all duration-200 text-gray-700
              ${selectedAnswer === index
                ? 'bg-blue-100 border-[#003366] ring-2 ring-[#003366]/50'
                : 'bg-white border-gray-300 hover:bg-gray-50 hover:border-[#003366]'
              }`}
          >
            <span className={`font-bold mr-3 ${selectedAnswer === index ? 'text-[#003366]' : 'text-gray-500'}`}>{String.fromCharCode(65 + index)}:</span> {option}
          </button>
        ))}
      </div>

      <div className="mt-8 flex justify-between items-center">
        <button
          onClick={handlePrev}
          disabled={currentQuestionIndex === 0}
          className="bg-gray-200 text-gray-700 font-bold py-2 px-6 rounded-lg hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Zurück
        </button>
        {currentQuestionIndex < questions.length - 1 ? (
          <button
            onClick={handleNext}
            className="bg-[#003366] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#002244] transition-colors"
          >
            Weiter
          </button>
        ) : (
          <button
            onClick={onSubmit}
            className="bg-green-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-700 transition-colors"
          >
            Abschicken
          </button>
        )}
      </div>
    </div>
  );
};

