import React, { useState, useCallback } from 'react';
import { Question } from './types';
import TopicSelector from './components/TopicSelector';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Loader from './components/Loader';
import Login from './components/Login';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';
import { generateQuiz } from './services/geminiService';

type GameState = 'config' | 'quiz' | 'results';
type View = 'user' | 'admin_login' | 'admin_panel';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [gameState, setGameState] = useState<GameState>('config');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<View>('user');

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleStartQuiz = useCallback(async (topic: string, numQuestions: number) => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedQuestions = await generateQuiz(topic, numQuestions);
      setQuestions(fetchedQuestions);
      setUserAnswers(new Array(fetchedQuestions.length).fill(null));
      setGameState('quiz');
    } catch (err) {
      setError('Fehler beim Generieren des Quiz. Bitte versuchen Sie es später erneut.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleAnswerSelect = (questionIndex: number, answerIndex: number) => {
    setUserAnswers(prev => {
      const newAnswers = [...prev];
      newAnswers[questionIndex] = answerIndex;
      return newAnswers;
    });
  };

  const handleSubmitQuiz = () => {
    setGameState('results');
  };

  const handleRestart = () => {
    setGameState('config');
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderUserContent = () => {
    if (isLoading) {
      return <Loader message="Quiz wird generiert... Bitte haben Sie einen Moment Geduld." />;
    }

    if (error) {
        return (
            <div className="text-center p-8 bg-white rounded-lg shadow-xl">
