import { GoogleGenAI, Type } from "@google/genai";
import { Question } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const DEFAULT_PROMPT_TEMPLATE = `Erstelle ein Multiple-Choice-Quiz auf Deutsch mit {numQuestions} Fragen zum Thema "{topic}". Jede Frage sollte 4 Antwortmöglichkeiten haben, von denen nur eine richtig ist. Gib für jede Frage auch eine kurze Erklärung für die richtige Antwort. Die Fragen sollten für Studenten geeignet sein, die sich auf eine Abschlussprüfung vorbereiten. Die Schwierigkeit sollte angemessen sein. Gib die Antwort ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht. Füge keine Markdown-Formatierung oder andere Texte außerhalb des JSON-Objekts hinzu.`;

export const generateQuiz = async (topic: string, numQuestions: number): Promise<Question[]> => {
  const promptTemplate = localStorage.getItem('admin_prompt_template') || DEFAULT_PROMPT_TEMPLATE;
  const prompt = promptTemplate
    .replace('{numQuestions}', String(numQuestions))
    .replace('{topic}', topic);


  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        questionText: { type: Type.STRING },
        options: {
          type: Type.ARRAY,
          items: { type: Type.STRING },
        },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING },
      },
      required: ['questionText', 'options', 'correctAnswerIndex', 'explanation'],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const jsonText = response.text.trim();
    const quizData = JSON.parse(jsonText);

    // Basic validation
    if (!Array.isArray(quizData) || quizData.length === 0) {
        throw new Error("API hat ein leeres oder ungültiges Quiz zurückgegeben.");
    }

    return quizData as Question[];
  } catch (error) {
    console.error("Fehler bei der Gemini-API-Anfrage:", error);
    throw new Error("Die Quizfragen konnten nicht generiert werden.");
  }
};

