  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  const [prompt, setPrompt] = useState('');
  const [promptSaveStatus, setPromptSaveStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [parsedQuestions, setParsedQuestions] = useState<Question[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState<string | null>(null);


  useEffect(() => {
    const savedPrompt = localStorage.getItem('admin_prompt_template');
    setPrompt(savedPrompt || DEFAULT_PROMPT_TEMPLATE);
  }, []);

  const handlePromptSave = () => {
    try {
      localStorage.setItem('admin_prompt_template', prompt);
      setPromptSaveStatus('success');
      setTimeout(() => setPromptSaveStatus('idle'), 2000);
    } catch (e) {
      console.error("Fehler beim Speichern des Prompts:", e);
      setPromptSaveStatus('error');
      setTimeout(() => setPromptSaveStatus('idle'), 2000);
    }
  };

  const handlePromptReset = () => {
    localStorage.removeItem('admin_prompt_template');
    setPrompt(DEFAULT_PROMPT_TEMPLATE);
    setPromptSaveStatus('success');
    setTimeout(() => setPromptSaveStatus('idle'), 2000);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setParsedQuestions([]);
      setSaveSuccess(null);
    }
  };

  const handleAnalyze = useCallback(() => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const content = e.target?.result as string;
      if (!content) {
        setError("Die Datei ist leer oder konnte nicht gelesen werden.");
        return;
      }

      setAnalyzing(true);
      setError(null);
      setSaveSuccess(null);
      try {
        const questions = await analyzeCsv(content);
        setParsedQuestions(questions);
      } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
      } finally {
        setAnalyzing(false);
      }
    };
    reader.readAsText(file);
  }, [file]);

  const handleQuestionChange = (index: number, field: keyof Question, value: any) => {
    const newQuestions = [...parsedQuestions];
    (newQuestions[index] as any)[field] = value;
    setParsedQuestions(newQuestions);
  };

  const handleOptionChange = (qIndex: number, oIndex: number, value: string) => {
    const newQuestions = [...parsedQuestions];
    newQuestions[qIndex].options[oIndex] = value;
    setParsedQuestions(newQuestions);
  };

  const handleDeleteQuestion = (index: number) => {
    setParsedQuestions(parsedQuestions.filter((_, i) => i !== index));
  };

  const handleSaveToDb = async () => {
    if (parsedQuestions.length === 0) return;

    setSaving(true);
    setError(null);
    setSaveSuccess(null);
    try {
      await saveQuestions(parsedQuestions);
      setSaveSuccess(`${parsedQuestions.length} Fragen wurden erfolgreich in der Datenbank gespeichert.`);
      setParsedQuestions([]);
      setFile(null);
    } catch (err: any) {
      setError(err.message || "Fehler beim Speichern in der Datenbank.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto my-8 p-8 bg-white rounded-xl shadow-lg">
      <header className="flex justify-between items-center border-b pb-4 mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Admin-Bereich</h1>
        <button
          onClick={onLogout}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300 transition-colors"
        >
          Logout
        </button>
      </header>

      {/* CSV UPLOAD SECTION */}
      <div className="space-y-4 border-b pb-8 mb-8">
        <h2 className="text-2xl font-semibold text-gray-700">Fragen-Management per Datei-Upload</h2>
        <p className="text-sm text-gray-600 bg-slate-100 p-3 rounded-lg">
            Laden Sie eine CSV-Datei mit Ihren Quizfragen hoch. Die KI wird versuchen, die Spalten für Frage, Antworten, korrekte Antwort und Erklärung automatisch zu erkennen. Überprüfen Sie die Ergebnisse vor dem Speichern.
        </p>

        <div className="flex items-center space-x-4">
            <input type="file" accept=".csv" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            <button onClick={handleAnalyze} disabled={!file || analyzing} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
                {analyzing ? 'Analysiere...' : 'Analysieren'}
            </button>
        </div>

        {error && <p className="text-red-600 font-semibold mt-2">{error}</p>}
        {saveSuccess && <p className="text-green-600 font-semibold mt-2">{saveSuccess}</p>}

        {parsedQuestions.length > 0 && (
          <div className="mt-6">
            <h3 className="text-xl font-semibold mb-4">Überprüfung der Fragen ({parsedQuestions.length})</h3>
            <div className="space-y-4 max-h-[50vh] overflow-y-auto pr-2">
              {parsedQuestions.map((q, qIndex) => (
                <div key={qIndex} className="bg-slate-50 p-4 rounded-lg border">
                  <div className="flex justify-between items-center mb-2">
                    <label className="block text-sm font-medium text-gray-700">Frage {qIndex + 1}</label>
                    <button onClick={() => handleDeleteQuestion(qIndex)} className="text-red-500 hover:text-red-700 text-sm font-semibold">Löschen</button>
                  </div>
                  <textarea value={q.questionText} onChange={(e) => handleQuestionChange(qIndex, 'questionText', e.target.value)} className="w-full p-2 border rounded"/>
                  <div className="grid grid-cols-2 gap-2 mt-2">
                    {q.options.map((opt, oIndex) => (
                      <input key={oIndex} type="text" value={opt} onChange={(e) => handleOptionChange(qIndex, oIndex, e.target.value)} className="w-full p-2 border rounded"/>
                    ))}
                  </div>
                   <div className="mt-2">
                     <label className="block text-sm font-medium text-gray-700">Korrekte Antwort</label>
                     <select value={q.correctAnswerIndex} onChange={(e) => handleQuestionChange(qIndex, 'correctAnswerIndex', parseInt(e.target.value))} className="w-full p-2 border rounded">
                        {q.options.map((opt, oIndex) => <option key={oIndex} value={oIndex}>{String.fromCharCode(65 + oIndex)}: {opt}</option>)}
                     </select>
                   </div>
                   <div className="mt-2">
                     <label className="block text-sm font-medium text-gray-700">Erklärung</label>
                     <textarea value={q.explanation} onChange={(e) => handleQuestionChange(qIndex, 'explanation', e.target.value)} className="w-full p-2 border rounded"/>
                   </div>
                </div>
              ))}
            </div>
            <div className="text-right mt-6">
              <button onClick={handleSaveToDb} disabled={saving} className="bg-green-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-green-700 transition-colors disabled:bg-gray-400">
                {saving ? 'Speichern...' : 'In Datenbank speichern'}
              </button>
            </div>
          </div>
        )}
      </div>

      {/* PROMPT MANAGEMENT SECTION */}
      <div className="space-y-4">
        <h2 className="text-2xl font-semibold text-gray-700">Prompt-Verwaltung für KI-Quiz</h2>
        <p className="text-sm text-gray-600 bg-slate-100 p-3 rounded-lg">
          Hier können Sie die Textvorlage (Prompt) bearbeiten, die zur Generierung der KI-Quizfragen verwendet wird.
          Die Platzhalter <code className="font-mono bg-slate-200 px-1 rounded">{'{numQuestions}'}</code> und <code className="font-mono bg-slate-200 px-1 rounded">{'{topic}'}</code> müssen erhalten bleiben.
        </p>

        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          className="w-full h-60 p-4 border border-gray-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-[#0B79D0] focus:border-transparent transition"
          aria-label="Prompt-Vorlage"
        />

        <div className="flex items-center justify-end space-x-4 pt-4">
            {promptSaveStatus === 'success' && <p className="text-green-600 font-semibold animate-pulse">Gespeichert!</p>}
            {promptSaveStatus === 'error' && <p className="text-red-600 font-semibold">Fehler!</p>}
          <button
            onClick={handlePromptReset}
            className="bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors"
          >
            Auf Standard zurücksetzen
          </button>
          <button
            onClick={handlePromptSave}
            className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors"
          >
            Änderungen speichern
          </button>
        </div>
      </div>
    </div>
  );
};

