      const dataUrl = e.target?.result as string;
      if (!dataUrl) {
        setError("Die Datei ist leer oder konnte nicht gelesen werden.");
        return;
      }

      const base64Data = dataUrl.split(',')[1];
       if (!base64Data) {
        setError("Fehler beim Verarbeiten der Datei.");
        return;
      }

      setAnalyzing(true);
      setError(null);
      setSaveSuccess(null);
      try {
        const questions = await analyzeFile({ mimeType: file.type, data: base64Data });
        setParsedQuestions(questions);
      } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
      } finally {
        setAnalyzing(false);
      }
    };
    reader.onerror = () => {
      setError("Fehler beim Lesen der Datei.");
      setAnalyzing(false);
    };
    reader.readAsDataURL(file);
  }, [file]);

  const handleQuestionChange = (index: number, field: keyof Question, value: any) => {
    const newQuestions = [...parsedQuestions];
    (newQuestions[index] as any)[field] = value;
    setParsedQuestions(newQuestions);
  };

  const handleOptionChange = (qIndex: number, oIndex: number, value: string) => {
    const newQuestions = [...parsedQuestions];
    newQuestions[qIndex].options[oIndex] = value;
    setParsedQuestions(newQuestions);
  };

  const handleDeleteQuestion = (index: number) => {
    setParsedQuestions(parsedQuestions.filter((_, i) => i !== index));
  };

  const handleSaveToDb = async () => {
    if (parsedQuestions.length === 0) return;

    setSaving(true);
    setError(null);
    setSaveSuccess(null);
    try {
      await saveQuestions(parsedQuestions);
      setSaveSuccess(`${parsedQuestions.length} Fragen wurden erfolgreich in der Datenbank gespeichert.`);
      setParsedQuestions([]);
      setFile(null);
    } catch (err: any) {
      setError(err.message || "Fehler beim Speichern in der Datenbank.");
    } finally {
      setSaving(false);
    }
  };

