      <header className="flex justify-between items-center border-b pb-4 mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Admin-Bereich</h1>
        <button
          onClick={onLogout}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300 transition-colors"
        >
          Logout
        </button>
      </header>

      {/* CSV UPLOAD SECTION */}
      <div className="space-y-4 border-b pb-8 mb-8">
        <h2 className="text-2xl font-semibold text-gray-700">Fragen-Management per Datei-Upload</h2>
        <p className="text-sm text-gray-600 bg-slate-100 p-3 rounded-lg">
            Laden Sie eine Datei (CSV, PDF, DOCX, etc.) mit Ihren Quizfragen hoch. Die KI wird versuchen, die Spalten für Frage, Antworten, korrekte Antwort und Erklärung automatisch zu erkennen. Überprüfen Sie die Ergebnisse vor dem Speichern.
        </p>

        <div className="flex items-center space-x-4">
            <input 
              type="file" 
              accept=".csv,text/csv,.pdf,application/pdf,.doc,application/msword,.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,.xls,application/vnd.ms-excel,.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/plain" 
              onChange={handleFileChange} 
              className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"
            />
            <button onClick={handleAnalyze} disabled={!file || analyzing} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
                {analyzing ? 'Analysiere...' : 'Analysieren'}
            </button>
        </div>

        {error && <p className="text-red-600 font-semibold mt-2">{error}</p>}
        {saveSuccess && <p className="text-green-600 font-semibold mt-2">{saveSuccess}</p>}

        {parsedQuestions.length > 0 && (
          <div className="mt-6">
            <h3 className="text-xl font-semibold mb-4">Überprüfung der Fragen ({parsedQuestions.length})</h3>
            <div className="space-y-4 max-h-[50vh] overflow-y-auto pr-2">
              {parsedQuestions.map((q, qIndex) => (
                <div key={qIndex} className="bg-slate-50 p-4 rounded-lg border">
                  <div className="flex justify-between items-center mb-2">
                    <label className="block text-sm font-medium text-gray-700">Frage {qIndex + 1}</label>
                    <button onClick={() => handleDeleteQuestion(qIndex)} className="text-red-500 hover:text-red-700 text-sm font-semibold">Löschen</button>
