                        {q.options.map((opt, oIndex) => <option key={oIndex} value={oIndex}>{String.fromCharCode(65 + oIndex)}: {opt}</option>)}
                     </select>
                   </div>
                   <div className="mt-2">
                     <label className="block text-sm font-medium text-gray-700">Erklärung</label>
                     <textarea value={q.explanation} onChange={(e) => handleQuestionChange(qIndex, 'explanation', e.target.value)} className="w-full p-2 border rounded"/>
                   </div>
                </div>
              ))}
            </div>
            <div className="text-right mt-6">
              <button onClick={handleSaveToDb} disabled={saving} className="bg-green-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-green-700 transition-colors disabled:bg-gray-400">
                {saving ? 'Speichern...' : 'In Datenbank speichern'}
              </button>
            </div>
          </div>
        )}
      </div>

      {/* PROMPT MANAGEMENT SECTION */}
      <div className="space-y-4">
        <h2 className="text-2xl font-semibold text-gray-700">Prompt-Verwaltung für KI-Quiz</h2>
        <p className="text-sm text-gray-600 bg-slate-100 p-3 rounded-lg">
          Hier können Sie die Textvorlage (Prompt) bearbeiten, die zur Generierung der KI-Quizfragen verwendet wird.
          Die Platzhalter <code className="font-mono bg-slate-200 px-1 rounded">{'{numQuestions}'}</code> und <code className="font-mono bg-slate-200 px-1 rounded">{'{topic}'}</code> müssen erhalten bleiben.
        </p>

        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          className="w-full h-60 p-4 border border-gray-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-[#0B79D0] focus:border-transparent transition"
          aria-label="Prompt-Vorlage"
        />

        <div className="flex items-center justify-end space-x-4 pt-4">
            {promptSaveStatus === 'success' && <p className="text-green-600 font-semibold animate-pulse">Gespeichert!</p>}
