import { GoogleGenAI, Type } from "@google/genai";
import { Question } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const DEFAULT_PROMPT_TEMPLATE = `Erstelle ein Multiple-Choice-Quiz auf Deutsch mit {numQuestions} Fragen zum Thema "{topic}". Jede Frage sollte 4 Antwortmöglichkeiten haben, von denen nur eine richtig ist. Gib für jede Frage auch eine kurze Erklärung für die richtige Antwort. Die Fragen sollten für Studenten geeignet sein, die sich auf eine Abschlussprüfung vorbereiten. Die Schwierigkeit sollte angemessen sein. Gib die Antwort ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht. Füge keine Markdown-Formatierung oder andere Texte außerhalb des JSON-Objekts hinzu.`;

const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        questionText: { type: Type.STRING },
        options: {
          type: Type.ARRAY,
          items: { type: Type.STRING },
          minItems: 4,
          maxItems: 4,
        },
        correctAnswerIndex: { type: Type.INTEGER },
        explanation: { type: Type.STRING },
      },
      required: ['questionText', 'options', 'correctAnswerIndex', 'explanation'],
    },
  };

export const generateQuiz = async (topic: string, numQuestions: number): Promise<Question[]> => {
  const promptTemplate = localStorage.getItem('admin_prompt_template') || DEFAULT_PROMPT_TEMPLATE;
  const prompt = promptTemplate
    .replace('{numQuestions}', String(numQuestions))
    .replace('{topic}', topic);

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    const jsonText = response.text.trim();
    const quizData = JSON.parse(jsonText);

    if (!Array.isArray(quizData) || quizData.length === 0) {
        throw new Error("API hat ein leeres oder ungültiges Quiz zurückgegeben.");
    }

    return quizData as Question[];
  } catch (error) {
    console.error("Fehler bei der Gemini-API-Anfrage:", error);
    throw new Error("Die Quizfragen konnten nicht generiert werden.");
  }
};

export const analyzeTextContent = async (textContent: string): Promise<Question[]> => {
  const prompt = `Analysiere den folgenden Text und extrahiere die Quizfragen daraus. Jede Frage sollte einen Fragetext, vier Antwortmöglichkeiten, eine korrekte Antwort und eine Erklärung haben. Identifiziere diese Elemente aus dem Text. Die korrekte Antwort kann als Text oder als Buchstabe (A, B, C, D) angegeben sein; wandle sie in den korrekten Index (0-3) um. Gib das Ergebnis ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht.

Hier ist der Text, der analysiert werden soll:
---
${textContent}
---
`;

  try {
     const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
      },
    });

    const jsonText = response.text.trim();
    const quizData = JSON.parse(jsonText);

    if (!Array.isArray(quizData) || quizData.length === 0) {
        throw new Error("Die KI konnte keine validen Fragen aus dem Text extrahieren.");
    }

    return quizData as Question[];
  } catch (error) {
    console.error("Fehler bei der Analyse des Textes durch die Gemini-API:", error);
    const message = error instanceof Error ? error.message : "Der Textinhalt konnte nicht analysiert werden.";
    throw new Error(message);
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { DEFAULT_PROMPT_TEMPLATE, analyzeTextContent } from '../services/geminiService';
import { saveQuestions } from '../services/supabaseService';
import { Question } from '../types';
import * as XLSX from 'xlsx';
import mammoth from 'mammoth';
import * as pdfjs from 'pdfjs-dist';

// Configure the PDF.js worker to enable client-side PDF processing.
pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.178/build/pdf.worker.mjs`;

interface AdminPanelProps {
  onLogout: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  const [prompt, setPrompt] = useState('');
  const [promptSaveStatus, setPromptSaveStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [parsedQuestions, setParsedQuestions] = useState<Question[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState<string | null>(null);


  useEffect(() => {
    const savedPrompt = localStorage.getItem('admin_prompt_template');
    setPrompt(savedPrompt || DEFAULT_PROMPT_TEMPLATE);
  }, []);

  const handlePromptSave = () => {
    try {
      localStorage.setItem('admin_prompt_template', prompt);
      setPromptSaveStatus('success');
      setTimeout(() => setPromptSaveStatus('idle'), 2000);
    } catch (e) {
      console.error("Fehler beim Speichern des Prompts:", e);
      setPromptSaveStatus('error');
      setTimeout(() => setPromptSaveStatus('idle'), 2000);
    }
  };

  const handlePromptReset = () => {
    localStorage.removeItem('admin_prompt_template');
    setPrompt(DEFAULT_PROMPT_TEMPLATE);
    setPromptSaveStatus('success');
    setTimeout(() => setPromptSaveStatus('idle'), 2000);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setParsedQuestions([]);
      setSaveSuccess(null);
    }
  };

  const handleAnalyze = useCallback(async () => {
    if (!file) return;

    setAnalyzing(true);
    setError(null);
    setSaveSuccess(null);

    try {
        let textContent = '';
        const fileType = file.type;
        const fileName = file.name.toLowerCase();

        if (fileType === 'text/plain' || fileType === 'text/csv' || fileName.endsWith('.csv')) {
            textContent = await file.text();
        } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await pdfjs.getDocument(arrayBuffer).promise;
            let fullText = '';
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const pageText = await page.getTextContent();
                fullText += pageText.items.map((item: any) => item.str).join(' ') + '\n';
            }
            textContent = fullText;
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
            const arrayBuffer = await file.arrayBuffer();
            const result = await mammoth.extractRawText({ arrayBuffer });
            textContent = result.value;
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
            const arrayBuffer = await file.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: 'array' });
            let fullText = '';
            workbook.SheetNames.forEach(sheetName => {
                const worksheet = workbook.Sheets[sheetName];
                const csv = XLSX.utils.sheet_to_csv(worksheet);
                fullText += csv + '\n';
            });
            textContent = fullText;
        } else {
            throw new Error(`Dateityp "${file.type || 'unbekannt'}" wird nicht unterstützt. Bitte verwenden Sie Text, CSV, PDF, DOCX oder XLSX.`);
        }

        if (!textContent.trim()) {
            throw new Error('Die Datei ist leer oder es konnte kein Text extrahiert werden.');
        }

        const questions = await analyzeTextContent(textContent);
        setParsedQuestions(questions);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
    }
  }, [file]);

  const handleQuestionChange = (index: number, field: keyof Question, value: any) => {
    const newQuestions = [...parsedQuestions];
    (newQuestions[index] as any)[field] = value;
    setParsedQuestions(newQuestions);
  };

  const handleOptionChange = (qIndex: number, oIndex: number, value: string) => {
    const newQuestions = [...parsedQuestions];
    newQuestions[qIndex].options[oIndex] = value;
    setParsedQuestions(newQuestions);
  };

  const handleDeleteQuestion = (index: number) => {
    setParsedQuestions(parsedQuestions.filter((_, i) => i !== index));
  };

  const handleSaveToDb = async () => {
    if (parsedQuestions.length === 0) return;

    setSaving(true);
    setError(null);
    setSaveSuccess(null);
    try {
      await saveQuestions(parsedQuestions);
      setSaveSuccess(`${parsedQuestions.length} Fragen wurden erfolgreich in der Datenbank gespeichert.`);
      setParsedQuestions([]);
      setFile(null);
    } catch (err: any) {
      setError(err.message || "Fehler beim Speichern in der Datenbank.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto my-8 p-8 bg-white rounded-xl shadow-lg">
      <header className="flex justify-between items-center border-b pb-4 mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Admin-Bereich</h1>
        <button
          onClick={onLogout}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300 transition-colors"
        >
          Logout
        </button>
      </header>

      {/* FILE UPLOAD SECTION */}
      <div className="space-y-4 border-b pb-8 mb-8">
        <h2 className="text-2xl font-semibold text-gray-700">Fragen-Management per Datei-Upload</h2>
        <p className="text-sm text-gray-600 bg-slate-100 p-3 rounded-lg">
            Laden Sie eine Datei (PDF, DOCX, XLSX, CSV, TXT) mit Ihren Quizfragen hoch. Die KI wird den Inhalt analysieren und die Fragen extrahieren. Überprüfen Sie die Ergebnisse vor dem Speichern.
        </p>

        <div className="flex items-center space-x-4">
