            throw new Error(`Dateityp "${file.type || 'unbekannt'}" wird nicht unterstützt. Bitte verwenden Sie Text, CSV, PDF, DOCX oder XLSX.`);
        }

        setAnalysisProgress(40);
        setAnalysisStatusMessage('Text wird extrahiert...');
        await new Promise(resolve => setTimeout(resolve, 200));

        if (!textContent.trim()) {
            throw new Error('Die Datei ist leer oder es konnte kein Text extrahiert werden.');
        }

        setAnalysisProgress(70);
        setAnalysisStatusMessage('Text wird mit KI analysiert...');

        const questions = await analyzeTextContent(textContent);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Analyse abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 500)); 

        setParsedQuestions(questions);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file]);

