        fetchQuestions(); // Refresh data
        setFile(null);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
