/**
 * Speichert ein Array von Fragen in der Supabase-Datenbank.
 * @param questions Ein Array von Question-Objekten.
 */
export const saveQuestions = async (questions: Omit<Question, 'id' | 'created_at'>[]): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { error } = await supabase
    .from('questions')
    .insert(questions);

  if (error) {
    console.error('Fehler beim Speichern der Fragen in Supabase:', error);
    throw new Error('Fragen konnten nicht in der Datenbank gespeichert werden.');
  }
};


/**
 * Holt eine zufällige Anzahl von Fragen aus der Supabase-Datenbank.
 * @param count Die Anzahl der zufälligen Fragen, die abgerufen werden sollen.
 * @returns Ein Promise, das zu einem Array von Question-Objekten aufgelöst wird.
 */
export const fetchRandomQuestions = async (count: number): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    // Hole alle Fragen. Für sehr große Tabellen wäre ein PL/pgSQL-Funktion performanter.
    const { data, error } = await supabase
        .from('questions')
        .select('*');

    if (error) {
        console.error('Fehler beim Abrufen der Fragen aus Supabase:', error);
        throw new Error('Fragen konnten nicht aus der Datenbank geladen werden.');
    }

    if (!data || data.length === 0) {
        throw new Error('Keine Fragen in der Datenbank gefunden.');
    }

    // Mische das Array und wähle die ersten 'count' Elemente aus.
    const shuffled = data.sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count) as Question[];
};

/**
 * Holt alle Fragen aus der Datenbank.
 */
export const fetchAllQuestions = async (): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .order('id', { ascending: true });

    if (error) {
        console.error('Fehler beim Abrufen aller Fragen:', error);
        throw new Error('Fragen konnten nicht geladen werden.');
    }
    return data as Question[];
};

/**
 * Erstellt eine neue Frage in der Datenbank.
 */
export const createQuestion = async (question: Omit<Question, 'id' | 'created_at'>): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .insert([question])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen der Frage:', error);
        throw new Error('Frage konnte nicht erstellt werden.');
    }
    return data as Question;
};


/**
 * Aktualisiert eine bestehende Frage in der Datenbank.
 */
export const updateQuestion = async (question: Question): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (!question.id) throw new Error("Frage benötigt eine ID zum Aktualisieren.");

    const { id, created_at, ...updateData } = question;

    const { data, error } = await supabase
        .from('questions')
        .update(updateData)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren der Frage:', error);
        throw new Error('Frage konnte nicht aktualisiert werden.');
    }
    return data as Question;
};

/**
 * Löscht eine Frage aus der Datenbank.
 */
export const deleteQuestion = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .delete()
        .eq('id', id)
        .select();

    if (error) {
        console.error('Fehler beim Löschen der Frage:', error);
        throw new Error('Frage konnte nicht gelöscht werden.');
    }

    // Wenn RLS den Löschvorgang verhindert, ist der Fehler 'null', aber es werden keine Daten zurückgegeben.
    // Wir prüfen, ob der Löschvorgang tatsächlich erfolgreich war.
    if (!data || data.length === 0) {
      console.error('Löschen der Frage fehlgeschlagen: Zeile nicht gefunden oder keine Berechtigung.');
      throw new Error('Frage konnte nicht gelöscht werden. Möglicherweise fehlt die Berechtigung oder die Frage existiert nicht mehr.');
    }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { analyzeTextContent } from '../services/geminiService';
import { saveQuestions, fetchAllQuestions, deleteQuestion, updateQuestion, createQuestion } from '../services/supabaseService';
import { Question } from '../types';
import * as XLSX from 'xlsx';
import mammoth from 'mammoth';
import * as pdfjs from 'pdfjs-dist';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// Configure the PDF.js worker to enable client-side PDF processing.
pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.178/build/pdf.worker.mjs`;

interface AdminPanelProps {
  onLogout: () => void;
}

type SortDirection = 'asc' | 'desc';
type SortableKeys = 'questionText' | 'type' | 'category';

interface SortConfig {
    key: SortableKeys | null;
    direction: SortDirection;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  // State for file import
  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisStatusMessage, setAnalysisStatusMessage] = useState('');

  // State for question management
  const [allQuestions, setAllQuestions] = useState<Question[]>([]);
  const [isLoadingQuestions, setIsLoadingQuestions] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: null, direction: 'asc' });


  // State for modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingQuestion, setEditingQuestion] = useState<Question | null>(null);

  // General state
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const fetchQuestions = useCallback(async () => {
    setIsLoadingQuestions(true);
    try {
      const questions = await fetchAllQuestions();
      setAllQuestions(questions);
    } catch (err: any) {
      setError(err.message || "Fehler beim Laden der Fragen.");
    } finally {
      setIsLoadingQuestions(false);
    }
  }, []);

  useEffect(() => {
    fetchQuestions();
  }, [fetchQuestions]);

  const showSuccessMessage = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => setSuccessMessage(null), 3000);
  };

  // File Upload and Analysis Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setSuccessMessage(null);
    }
  };

  const handleAnalyzeAndImport = useCallback(async () => {
    if (!file) return;

    setAnalyzing(true);
    setError(null);
    setSuccessMessage(null);
    const allParsedQuestions: Question[] = [];

    try {
        setAnalysisProgress(5);
        setAnalysisStatusMessage('Datei wird gelesen...');
        await new Promise(resolve => setTimeout(resolve, 200));

        let textContent = '';
        const fileType = file.type;
        const fileName = file.name.toLowerCase();

        if (fileType === 'text/plain' || fileType === 'text/csv' || fileName.endsWith('.csv')) {
            textContent = await file.text();
        } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await pdfjs.getDocument(arrayBuffer).promise;
            textContent = (await Promise.all(Array.from({ length: pdf.numPages }, (_, i) => pdf.getPage(i + 1).then(page => page.getTextContent()))))
                .map(content => content.items.map((item: any) => item.str).join(' ')).join('\n\n');
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
            const arrayBuffer = await file.arrayBuffer();
            const result = await mammoth.extractRawText({ arrayBuffer });
            textContent = result.value;
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
            const arrayBuffer = await file.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: 'array' });
            textContent = workbook.SheetNames.map(sheetName => XLSX.utils.sheet_to_csv(workbook.Sheets[sheetName])).join('\n');
        } else {
            throw new Error(`Dateityp wird nicht unterstützt. Bitte TXT, CSV, PDF, DOCX oder XLSX verwenden.`);
        }

        setAnalysisProgress(10);
        setAnalysisStatusMessage('Text wird extrahiert...');
        await new Promise(resolve => setTimeout(resolve, 200));

        if (!textContent.trim()) throw new Error('Kein Text in der Datei gefunden.');

        // Chunking the text to handle large files
        const chunks = textContent.split(/\n\s*\n/).filter(chunk => chunk.trim().length > 20); // Split by blank lines

        for (let i = 0; i < chunks.length; i++) {
            const chunk = chunks[i];
            const progress = 10 + Math.round(((i + 1) / chunks.length) * 80);
            setAnalysisProgress(progress);
            setAnalysisStatusMessage(`KI analysiert Block ${i + 1} von ${chunks.length}...`);

            const parsedChunk = await analyzeTextContent(chunk);
            if (parsedChunk && parsedChunk.length > 0) {
                allParsedQuestions.push(...parsedChunk);
            }
        }

        if (allParsedQuestions.length === 0) {
          throw new Error("Es konnten keine Fragen aus der Datei extrahiert werden. Überprüfen Sie das Format.");
        }

        setAnalysisProgress(95);
        setAnalysisStatusMessage('Fragen werden importiert...');
        await saveQuestions(allParsedQuestions);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Import abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 500)); 

        showSuccessMessage(`${allParsedQuestions.length} Fragen erfolgreich importiert!`);
        fetchQuestions(); // Refresh data
        setFile(null);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file, fetchQuestions]);

  // Question Management Logic
  const handleOpenModal = (question?: Question) => {
    setEditingQuestion(question || { questionText: '', options: ['', '', '', ''], correctAnswerIndex: 0, explanation: '', category: 'Hundeführerschein', type: 'Single Choice' });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingQuestion(null);
  };

  const handleSaveQuestion = async (questionToSave: Question) => {
    try {
      if (questionToSave.id) {
        await updateQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich aktualisiert.');
      } else {
        await createQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich erstellt.');
      }
      fetchQuestions();
      handleCloseModal();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleDeleteQuestion = async (id: number) => {
    if (window.confirm('Sind Sie sicher, dass Sie diese Frage löschen möchten?')) {
      try {
        await deleteQuestion(id);
        showSuccessMessage('Frage gelöscht.');
        setAllQuestions(prev => prev.filter(q => q.id !== id));
      } catch (err: any) {
        setError(err.message);
      }
    }
  };

  const handleExportCSV = () => {
    const dataToExport = filteredAndSortedQuestions.map(q => ({
      ID: q.id,
      Frage: q.questionText,
      Typ: q.type,
      Kategorie: q.category,
      Antwort_A: q.options[0],
      Antwort_B: q.options[1],
      Antwort_C: q.options[2],
      Antwort_D: q.options[3],
      Korrekter_Index: q.correctAnswerIndex,
      Erklaerung: q.explanation,
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Fragen");
    XLSX.writeFile(workbook, "fragen-export.csv", { bookType: "csv" });
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Fragenkatalog - DZKB Bayern e.V.", 14, 22);

    autoTable(doc, {
        startY: 30,
        head: [['ID', 'Frage', 'Kategorie', 'Korrekte Antwort']],
        body: filteredAndSortedQuestions.map(q => [
            q.id,
            q.questionText,
            q.category,
            q.options[q.correctAnswerIndex]
        ]),
        styles: { overflow: 'linebreak', cellWidth: 'wrap', font: 'helvetica', fontSize: 8 },
        headStyles: { fillColor: [11, 121, 208] },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 'auto' },
            2: { cellWidth: 30 },
            3: { cellWidth: 40 }
        }
    });

    doc.save('fragen-katalog.pdf');
  };

  const categories = useMemo(() => ['all', ...Array.from(new Set(allQuestions.map(q => q.category).filter(Boolean)))], [allQuestions]) as string[];

  const requestSort = (key: SortableKeys) => {
      let direction: SortDirection = 'asc';
      if (sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const filteredAndSortedQuestions = useMemo(() => {
    let questions = allQuestions.filter(q => {
      const matchesCategory = categoryFilter === 'all' || q.category === categoryFilter;
      const matchesSearch = searchTerm === '' || 
        q.questionText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        q.options.some(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesCategory && matchesSearch;
    });

    if (sortConfig.key !== null) {
      questions.sort((a, b) => {
          const aValue = String(a[sortConfig.key!] ?? '').toLowerCase();
          const bValue = String(b[sortConfig.key!] ?? '').toLowerCase();

          if (sortConfig.direction === 'asc') {
              return aValue.localeCompare(bValue);
          } else {
              return bValue.localeCompare(aValue);
          }
      });
    }

    return questions;
  }, [allQuestions, searchTerm, categoryFilter, sortConfig]);

  const SortIndicator = ({ columnKey }: { columnKey: SortableKeys }) => {
    if (sortConfig.key !== columnKey) return <span className="ml-1 text-gray-300">↕</span>;
    if (sortConfig.direction === 'asc') return <span className="ml-1 text-[#0B79D0]">▲</span>;
    return <span className="ml-1 text-[#0B79D0]">▼</span>;
  };

  return (
    <div className="w-full min-h-screen bg-slate-100">
      {/* Header */}
      <header className="bg-[#0B79D0] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Admin Dashboard</h1>
          <button onClick={onLogout} className="bg-white text-[#0B79D0] font-bold py-2 px-5 rounded-lg hover:bg-slate-100 transition-colors">
            Sign Out
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Import/Export Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl shadow-lg">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Import</h2>
            <p className="text-sm text-gray-600 mb-4">Laden Sie eine Datei (PDF, DOCX, XLSX, etc.) hoch, um automatisch Fragen zu importieren.</p>
            <div className="flex items-center space-x-4">
              <input type="file" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            </div>
            {file && <button onClick={handleAnalyzeAndImport} disabled={analyzing} className="mt-4 w-full bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
              {analyzing ? 'Importiere...' : `"${file.name}" importieren`}
            </button>}
             {analyzing && <div className="mt-4 w-full">
                <div className="flex justify-between mb-1">
                    <span className="text-base font-medium text-slate-700">{analysisStatusMessage}</span>
                    <span className="text-sm font-medium text-[#0B79D0]">{analysisProgress}%</span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5"><div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${analysisProgress}%` }}></div></div>
              </div>}
          </div>
          <div className="bg-white p-6 rounded-xl shadow-lg">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Export</h2>
            <p className="text-sm text-gray-600 mb-4">Wählen Sie ein Format, um den aktuellen Fragenkatalog zu exportieren.</p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button onClick={handleExportCSV} className="flex-1 bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors">
                CSV Export
                </button>
                <button onClick={handleExportPDF} className="flex-1 bg-orange-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-orange-600 transition-colors">
                PDF Katalog
                </button>
            </div>
          </div>
        </div>

        {/* Question Management Table */}
        <div className="bg-white p-6 rounded-xl shadow-lg">
          <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
            <h2 className="text-xl font-bold text-gray-800">Fragen verwalten ({filteredAndSortedQuestions.length})</h2>
            <div className="flex items-center gap-4 w-full md:w-auto">
              <input type="text" placeholder="Suche..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-auto bg-white text-gray-900"/>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="p-2 border rounded-lg bg-white text-gray-900">
                {categories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'Alle Kategorien' : cat}</option>)}
              </select>
              <button onClick={() => handleOpenModal()} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 transition-colors whitespace-nowrap">+ Neue Frage</button>
            </div>
          </div>

          {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
          {successMessage && <p className="text-green-600 font-semibold mb-4">{successMessage}</p>}

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2">ID</th>
                   <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('questionText')}>
                      <div className="flex items-center">Frage <SortIndicator columnKey="questionText" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('type')}>
                      <div className="flex items-center">Typ <SortIndicator columnKey="type" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('category')}>
                      <div className="flex items-center">Kategorie <SortIndicator columnKey="category" /></div>
                    </th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {isLoadingQuestions ? (<tr><td colSpan={5} className="text-center p-4">Lade Fragen...</td></tr>) 
                : filteredAndSortedQuestions.map(q => (
                  <tr key={q.id} className="border-b hover:bg-slate-50 text-gray-800">
                    <td className="p-2 font-mono text-sm">{q.id}</td>
                    <td className="p-2 max-w-md truncate">{q.questionText}</td>
                    <td className="p-2"><span className="bg-blue-100 text-[#0B79D0] text-xs font-medium px-2.5 py-0.5 rounded-full">{q.type || 'N/A'}</span></td>
                    <td className="p-2">{q.category || 'N/A'}</td>
                    <td className="p-2 flex gap-4">
                      <button onClick={() => handleOpenModal(q)} className="text-[#0B79D0] font-semibold">Edit</button>
                      <button onClick={() => handleDeleteQuestion(q.id!)} className="text-red-500 font-semibold">Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {isModalOpen && editingQuestion && (
        <EditQuestionModal
          question={editingQuestion}
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          onSave={handleSaveQuestion}
        />
      )}
    </div>
  );
};


// Modal Component
interface EditQuestionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (question: Question) => void;
  question: Question;
}

const EditQuestionModal: React.FC<EditQuestionModalProps> = ({ isOpen, onClose, onSave, question }) => {
  const [editedQuestion, setEditedQuestion] = useState<Question>(question);

  useEffect(() => {
    setEditedQuestion(question);
  }, [question]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedQuestion(prev => ({...prev, [name]: value}));
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...editedQuestion.options];
    newOptions[index] = value;
    setEditedQuestion(prev => ({...prev, options: newOptions}));
  };

  const handleCorrectAnswerChange = (index: number) => {
    setEditedQuestion(prev => ({...prev, correctAnswerIndex: index}));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-6 text-gray-800">{editedQuestion.id ? 'Frage bearbeiten' : 'Neue Frage erstellen'}</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Fragetext</label>
            <textarea name="questionText" value={editedQuestion.questionText} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={4}/>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Kategorie</label>
              <input type="text" name="category" value={editedQuestion.category || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900"/>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700">Typ</label>
              <select name="type" value={editedQuestion.type || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                  <option value="Single Choice">Single Choice</option>
                  <option value="Multiple Choice">Multiple Choice</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Antworten (die erste ist A, die zweite B, usw.)</label>
            {editedQuestion.options.map((opt, index) => (
              <div key={index} className="flex items-center mt-2">
                <input type="radio" name="correctAnswer" checked={editedQuestion.correctAnswerIndex === index} onChange={() => handleCorrectAnswerChange(index)} className="mr-2 h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"/>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(index, e.target.value)} className="w-full p-2 border rounded bg-gray-50 text-gray-900"/>
              </div>
            ))}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Erklärung</label>
            <textarea name="explanation" value={editedQuestion.explanation} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={3}/>
          </div>
        </div>
        <div className="flex justify-end gap-4 mt-8">
          <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">Abbrechen</button>
          <button onClick={() => onSave(editedQuestion)} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4]">Speichern</button>
        </div>
      </div>
    </div>
  );
};


export default AdminPanel;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { analyzeTextContent } from '../services/geminiService';
import { saveQuestions, fetchAllQuestions, deleteQuestion, updateQuestion, createQuestion } from '../services/supabaseService';
import { Question } from '../types';
import * as XLSX from 'xlsx';
import mammoth from 'mammoth';
import * as pdfjs from 'pdfjs-dist';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// Configure the PDF.js worker to enable client-side PDF processing.
pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.178/build/pdf.worker.mjs`;

interface AdminPanelProps {
  onLogout: () => void;
}

type SortDirection = 'asc' | 'desc';
type SortableKeys = 'questionText' | 'type' | 'category';

interface SortConfig {
    key: SortableKeys | null;
    direction: SortDirection;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  // State for file import
  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisStatusMessage, setAnalysisStatusMessage] = useState('');

  // State for question management
  const [allQuestions, setAllQuestions] = useState<Question[]>([]);
  const [isLoadingQuestions, setIsLoadingQuestions] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: null, direction: 'asc' });


  // State for modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingQuestion, setEditingQuestion] = useState<Question | null>(null);

  // General state
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const fetchQuestions = useCallback(async () => {
    setIsLoadingQuestions(true);
    try {
      const questions = await fetchAllQuestions();
      setAllQuestions(questions);
    } catch (err: any) {
      setError(err.message || "Fehler beim Laden der Fragen.");
    } finally {
      setIsLoadingQuestions(false);
    }
  }, []);

  useEffect(() => {
    fetchQuestions();
  }, [fetchQuestions]);

  const showSuccessMessage = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => setSuccessMessage(null), 3000);
  };

  // File Upload and Analysis Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setSuccessMessage(null);
    }
  };

  const handleAnalyzeAndImport = useCallback(async () => {
    if (!file) return;

    setAnalyzing(true);
    setError(null);
    setSuccessMessage(null);
    const allParsedQuestions: Question[] = [];

    try {
        setAnalysisProgress(5);
        setAnalysisStatusMessage('Datei wird gelesen...');
        await new Promise(resolve => setTimeout(resolve, 200));

        let textContent = '';
        const fileType = file.type;
        const fileName = file.name.toLowerCase();

        if (fileType === 'text/plain' || fileType === 'text/csv' || fileName.endsWith('.csv')) {
            textContent = await file.text();
        } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await pdfjs.getDocument(arrayBuffer).promise;
            textContent = (await Promise.all(Array.from({ length: pdf.numPages }, (_, i) => pdf.getPage(i + 1).then(page => page.getTextContent()))))
                .map(content => content.items.map((item: any) => item.str).join(' ')).join('\n\n');
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
            const arrayBuffer = await file.arrayBuffer();
            const result = await mammoth.extractRawText({ arrayBuffer });
            textContent = result.value;
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
            const arrayBuffer = await file.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: 'array' });
            textContent = workbook.SheetNames.map(sheetName => XLSX.utils.sheet_to_csv(workbook.Sheets[sheetName])).join('\n');
        } else {
            throw new Error(`Dateityp wird nicht unterstützt. Bitte TXT, CSV, PDF, DOCX oder XLSX verwenden.`);
        }

        setAnalysisProgress(10);
        setAnalysisStatusMessage('Text wird extrahiert...');
        await new Promise(resolve => setTimeout(resolve, 200));

        if (!textContent.trim()) throw new Error('Kein Text in der Datei gefunden.');

        // Robust character-based chunking to handle large files reliably.
        const CHUNK_SIZE = 8000;
        const chunks = [];
        for (let i = 0; i < textContent.length; i += CHUNK_SIZE) {
            chunks.push(textContent.substring(i, i + CHUNK_SIZE));
        }

        for (let i = 0; i < chunks.length; i++) {
            const chunk = chunks[i];
            const progress = 10 + Math.round(((i + 1) / chunks.length) * 80);
            setAnalysisProgress(progress);
            setAnalysisStatusMessage(`KI analysiert Block ${i + 1} von ${chunks.length}...`);

            const parsedChunk = await analyzeTextContent(chunk);
            if (parsedChunk && parsedChunk.length > 0) {
                allParsedQuestions.push(...parsedChunk);
            }
        }

        if (allParsedQuestions.length === 0) {
          throw new Error("Es konnten keine Fragen aus der Datei extrahiert werden. Überprüfen Sie das Format.");
        }

        setAnalysisProgress(95);
        setAnalysisStatusMessage('Fragen werden importiert...');
        await saveQuestions(allParsedQuestions);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Import abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 500)); 

        showSuccessMessage(`${allParsedQuestions.length} Fragen erfolgreich importiert!`);
        fetchQuestions(); // Refresh data
        setFile(null);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file, fetchQuestions]);

  // Question Management Logic
  const handleOpenModal = (question?: Question) => {
    setEditingQuestion(question || { questionText: '', options: ['', '', '', ''], correctAnswerIndex: 0, explanation: '', category: 'Hundeführerschein', type: 'Single Choice' });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingQuestion(null);
  };

  const handleSaveQuestion = async (questionToSave: Question) => {
    try {
      if (questionToSave.id) {
        await updateQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich aktualisiert.');
      } else {
        await createQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich erstellt.');
      }
      fetchQuestions();
      handleCloseModal();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleDeleteQuestion = async (id: number) => {
    if (window.confirm('Sind Sie sicher, dass Sie diese Frage löschen möchten?')) {
      try {
        await deleteQuestion(id);
        showSuccessMessage('Frage gelöscht.');
        // Re-fetch questions from the database to ensure UI consistency.
        fetchQuestions();
      } catch (err: any) {
        setError(err.message);
      }
    }
  };

  const handleExportCSV = () => {
    const dataToExport = filteredAndSortedQuestions.map(q => ({
      ID: q.id,
      Frage: q.questionText,
      Typ: q.type,
      Kategorie: q.category,
      Antwort_A: q.options[0],
      Antwort_B: q.options[1],
      Antwort_C: q.options[2],
      Antwort_D: q.options[3],
      Korrekter_Index: q.correctAnswerIndex,
      Erklaerung: q.explanation,
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Fragen");
    XLSX.writeFile(workbook, "fragen-export.csv", { bookType: "csv" });
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Fragenkatalog - DZKB Bayern e.V.", 14, 22);

    autoTable(doc, {
        startY: 30,
        head: [['ID', 'Frage', 'Kategorie', 'Korrekte Antwort']],
        body: filteredAndSortedQuestions.map(q => [
            q.id,
            q.questionText,
            q.category,
            q.options[q.correctAnswerIndex]
        ]),
        styles: { overflow: 'linebreak', cellWidth: 'wrap', font: 'helvetica', fontSize: 8 },
        headStyles: { fillColor: [11, 121, 208] },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 'auto' },
            2: { cellWidth: 30 },
            3: { cellWidth: 40 }
        }
    });

    doc.save('fragen-katalog.pdf');
  };

  const categories = useMemo(() => ['all', ...Array.from(new Set(allQuestions.map(q => q.category).filter(Boolean)))], [allQuestions]) as string[];

  const requestSort = (key: SortableKeys) => {
      let direction: SortDirection = 'asc';
      if (sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const filteredAndSortedQuestions = useMemo(() => {
    let questions = allQuestions.filter(q => {
      const matchesCategory = categoryFilter === 'all' || q.category === categoryFilter;
      const matchesSearch = searchTerm === '' || 
        q.questionText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        q.options.some(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesCategory && matchesSearch;
    });

    if (sortConfig.key !== null) {
      questions.sort((a, b) => {
          const aValue = String(a[sortConfig.key!] ?? '').toLowerCase();
          const bValue = String(b[sortConfig.key!] ?? '').toLowerCase();

          if (sortConfig.direction === 'asc') {
              return aValue.localeCompare(bValue);
          } else {
              return bValue.localeCompare(aValue);
          }
      });
    }

    return questions;
  }, [allQuestions, searchTerm, categoryFilter, sortConfig]);

  const SortIndicator = ({ columnKey }: { columnKey: SortableKeys }) => {
    if (sortConfig.key !== columnKey) return <span className="ml-1 text-gray-300">↕</span>;
    if (sortConfig.direction === 'asc') return <span className="ml-1 text-[#0B79D0]">▲</span>;
    return <span className="ml-1 text-[#0B79D0]">▼</span>;
  };

  return (
    <div className="w-full min-h-screen bg-slate-100">
      {/* Header */}
      <header className="bg-[#0B79D0] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Admin Dashboard</h1>
          <button onClick={onLogout} className="bg-white text-[#0B79D0] font-bold py-2 px-5 rounded-lg hover:bg-slate-100 transition-colors">
            Sign Out
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Import/Export Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl shadow-lg">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Import</h2>
            <p className="text-sm text-gray-600 mb-4">Laden Sie eine Datei (PDF, DOCX, XLSX, etc.) hoch, um automatisch Fragen zu importieren.</p>
            <div className="flex items-center space-x-4">
              <input type="file" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            </div>
            {file && <button onClick={handleAnalyzeAndImport} disabled={analyzing} className="mt-4 w-full bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
              {analyzing ? 'Importiere...' : `"${file.name}" importieren`}
            </button>}
             {analyzing && <div className="mt-4 w-full">
                <div className="flex justify-between mb-1">
                    <span className="text-base font-medium text-slate-700">{analysisStatusMessage}</span>
                    <span className="text-sm font-medium text-[#0B79D0]">{analysisProgress}%</span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5"><div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${analysisProgress}%` }}></div></div>
              </div>}
          </div>
          <div className="bg-white p-6 rounded-xl shadow-lg">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Export</h2>
            <p className="text-sm text-gray-600 mb-4">Wählen Sie ein Format, um den aktuellen Fragenkatalog zu exportieren.</p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button onClick={handleExportCSV} className="flex-1 bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors">
                CSV Export
                </button>
                <button onClick={handleExportPDF} className="flex-1 bg-orange-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-orange-600 transition-colors">
                PDF Katalog
                </button>
            </div>
          </div>
        </div>

        {/* Question Management Table */}
        <div className="bg-white p-6 rounded-xl shadow-lg">
          <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
            <h2 className="text-xl font-bold text-gray-800">Fragen verwalten ({filteredAndSortedQuestions.length})</h2>
            <div className="flex items-center gap-4 w-full md:w-auto">
              <input type="text" placeholder="Suche..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-auto bg-white text-gray-900"/>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="p-2 border rounded-lg bg-white text-gray-900">
                {categories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'Alle Kategorien' : cat}</option>)}
              </select>
              <button onClick={() => handleOpenModal()} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 transition-colors whitespace-nowrap">+ Neue Frage</button>
            </div>
          </div>

          {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
          {successMessage && <p className="text-green-600 font-semibold mb-4">{successMessage}</p>}

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2">ID</th>
                   <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('questionText')}>
                      <div className="flex items-center">Frage <SortIndicator columnKey="questionText" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('type')}>
                      <div className="flex items-center">Typ <SortIndicator columnKey="type" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('category')}>
                      <div className="flex items-center">Kategorie <SortIndicator columnKey="category" /></div>
                    </th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {isLoadingQuestions ? (<tr><td colSpan={5} className="text-center p-4">Lade Fragen...</td></tr>) 
                : filteredAndSortedQuestions.map(q => (
                  <tr key={q.id} className="border-b hover:bg-slate-50 text-gray-800">
                    <td className="p-2 font-mono text-sm">{q.id}</td>
                    <td className="p-2 max-w-md truncate">{q.questionText}</td>
                    <td className="p-2"><span className="bg-blue-100 text-[#0B79D0] text-xs font-medium px-2.5 py-0.5 rounded-full">{q.type || 'N/A'}</span></td>
                    <td className="p-2">{q.category || 'N/A'}</td>
                    <td className="p-2 flex gap-4">
                      <button onClick={() => handleOpenModal(q)} className="text-[#0B79D0] font-semibold">Edit</button>
                      <button onClick={() => handleDeleteQuestion(q.id!)} className="text-red-500 font-semibold">Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {isModalOpen && editingQuestion && (
        <EditQuestionModal
          question={editingQuestion}
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          onSave={handleSaveQuestion}
        />
      )}
    </div>
  );
};


// Modal Component
interface EditQuestionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (question: Question) => void;
  question: Question;
}

const EditQuestionModal: React.FC<EditQuestionModalProps> = ({ isOpen, onClose, onSave, question }) => {
  const [editedQuestion, setEditedQuestion] = useState<Question>(question);

  useEffect(() => {
    setEditedQuestion(question);
  }, [question]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedQuestion(prev => ({...prev, [name]: value}));
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...editedQuestion.options];
    newOptions[index] = value;
    setEditedQuestion(prev => ({...prev, options: newOptions}));
  };

  const handleCorrectAnswerChange = (index: number) => {
    setEditedQuestion(prev => ({...prev, correctAnswerIndex: index}));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-6 text-gray-800">{editedQuestion.id ? 'Frage bearbeiten' : 'Neue Frage erstellen'}</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Fragetext</label>
            <textarea name="questionText" value={editedQuestion.questionText} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={4}/>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Kategorie</label>
              <input type="text" name="category" value={editedQuestion.category || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900"/>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700">Typ</label>
              <select name="type" value={editedQuestion.type || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                  <option value="Single Choice">Single Choice</option>
                  <option value="Multiple Choice">Multiple Choice</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Antworten (die erste ist A, die zweite B, usw.)</label>
            {editedQuestion.options.map((opt, index) => (
              <div key={index} className="flex items-center mt-2">
                <input type="radio" name="correctAnswer" checked={editedQuestion.correctAnswerIndex === index} onChange={() => handleCorrectAnswerChange(index)} className="mr-2 h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"/>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(index, e.target.value)} className="w-full p-2 border rounded bg-gray-50 text-gray-900"/>
              </div>
            ))}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Erklärung</label>
            <textarea name="explanation" value={editedQuestion.explanation} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={3}/>
          </div>
        </div>
        <div className="flex justify-end gap-4 mt-8">
          <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">Abbrechen</button>
          <button onClick={() => onSave(editedQuestion)} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4]">Speichern</button>
        </div>
      </div>
    </div>
  );
};


export default AdminPanel;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { analyzeTextContent } from '../services/geminiService';
import { saveQuestions, fetchAllQuestions, deleteQuestion, updateQuestion, createQuestion } from '../services/supabaseService';
import { Question } from '../types';
import * as XLSX from 'xlsx';
import mammoth from 'mammoth';
import * as pdfjs from 'pdfjs-dist';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// Configure the PDF.js worker to enable client-side PDF processing.
pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.178/build/pdf.worker.mjs`;

interface AdminPanelProps {
  onLogout: () => void;
}

type SortDirection = 'asc' | 'desc';
type SortableKeys = 'questionText' | 'type' | 'category';

interface SortConfig {
    key: SortableKeys | null;
    direction: SortDirection;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  // State for file import
  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisStatusMessage, setAnalysisStatusMessage] = useState('');

  // State for question management
  const [allQuestions, setAllQuestions] = useState<Question[]>([]);
  const [isLoadingQuestions, setIsLoadingQuestions] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: null, direction: 'asc' });


  // State for modals
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingQuestion, setEditingQuestion] = useState<Question | null>(null);
  const [questionToDelete, setQuestionToDelete] = useState<Question | null>(null);


  // General state
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const fetchQuestions = useCallback(async () => {
    setIsLoadingQuestions(true);
    try {
      const questions = await fetchAllQuestions();
      setAllQuestions(questions);
    } catch (err: any) {
      setError(err.message || "Fehler beim Laden der Fragen.");
    } finally {
      setIsLoadingQuestions(false);
    }
  }, []);

  useEffect(() => {
    fetchQuestions();
  }, [fetchQuestions]);

  const showSuccessMessage = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => setSuccessMessage(null), 3000);
  };

  // File Upload and Analysis Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setSuccessMessage(null);
    }
  };

  const handleAnalyzeAndImport = useCallback(async () => {
    if (!file) return;

    setAnalyzing(true);
    setError(null);
    setSuccessMessage(null);
    const allParsedQuestions: Question[] = [];

    try {
        setAnalysisProgress(5);
        setAnalysisStatusMessage('Datei wird gelesen...');
        await new Promise(resolve => setTimeout(resolve, 200));

        let textContent = '';
        const fileType = file.type;
        const fileName = file.name.toLowerCase();

        if (fileType === 'text/plain' || fileType === 'text/csv' || fileName.endsWith('.csv')) {
            textContent = await file.text();
        } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
            const arrayBuffer = await file.arrayBuffer();
            const pdf = await pdfjs.getDocument(arrayBuffer).promise;
            textContent = (await Promise.all(Array.from({ length: pdf.numPages }, (_, i) => pdf.getPage(i + 1).then(page => page.getTextContent()))))
                .map(content => content.items.map((item: any) => item.str).join(' ')).join('\n\n');
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
            const arrayBuffer = await file.arrayBuffer();
            const result = await mammoth.extractRawText({ arrayBuffer });
            textContent = result.value;
        } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
            const arrayBuffer = await file.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: 'array' });
            textContent = workbook.SheetNames.map(sheetName => XLSX.utils.sheet_to_csv(workbook.Sheets[sheetName])).join('\n');
        } else {
            throw new Error(`Dateityp wird nicht unterstützt. Bitte TXT, CSV, PDF, DOCX oder XLSX verwenden.`);
        }

        setAnalysisProgress(10);
        setAnalysisStatusMessage('Text wird extrahiert...');
        await new Promise(resolve => setTimeout(resolve, 200));

        if (!textContent.trim()) throw new Error('Kein Text in der Datei gefunden.');

        // Robust character-based chunking to handle large files reliably.
        const CHUNK_SIZE = 8000;
        const chunks = [];
        for (let i = 0; i < textContent.length; i += CHUNK_SIZE) {
            chunks.push(textContent.substring(i, i + CHUNK_SIZE));
        }

        for (let i = 0; i < chunks.length; i++) {
            const chunk = chunks[i];
            const progress = 10 + Math.round(((i + 1) / chunks.length) * 80);
            setAnalysisProgress(progress);
            setAnalysisStatusMessage(`KI analysiert Block ${i + 1} von ${chunks.length}...`);

            const parsedChunk = await analyzeTextContent(chunk);
            if (parsedChunk && parsedChunk.length > 0) {
                allParsedQuestions.push(...parsedChunk);
            }
        }

        if (allParsedQuestions.length === 0) {
          throw new Error("Es konnten keine Fragen aus der Datei extrahiert werden. Überprüfen Sie das Format.");
        }

        setAnalysisProgress(95);
        setAnalysisStatusMessage('Fragen werden importiert...');
        await saveQuestions(allParsedQuestions);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Import abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 500)); 

        showSuccessMessage(`${allParsedQuestions.length} Fragen erfolgreich importiert!`);
        fetchQuestions(); // Refresh data
        setFile(null);

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file, fetchQuestions]);

  // Question Management Logic
  const handleOpenEditModal = (question?: Question) => {
    setEditingQuestion(question || { questionText: '', options: ['', '', '', ''], correctAnswerIndex: 0, explanation: '', category: 'Hundeführerschein', type: 'Single Choice' });
    setIsEditModalOpen(true);
  };

  const handleCloseEditModal = () => {
    setIsEditModalOpen(false);
    setEditingQuestion(null);
  };

  const handleSaveQuestion = async (questionToSave: Question) => {
    try {
      if (questionToSave.id) {
        await updateQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich aktualisiert.');
      } else {
        await createQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich erstellt.');
      }
      fetchQuestions();
      handleCloseEditModal();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleDeleteRequest = (question: Question) => {
    setQuestionToDelete(question);
  };

  const handleDeleteConfirmed = async () => {
    if (!questionToDelete) return;
    try {
      await deleteQuestion(questionToDelete.id!);
      showSuccessMessage('Frage erfolgreich gelöscht.');
      setQuestionToDelete(null);
      fetchQuestions(); // Re-fetch all questions to guarantee UI consistency
    } catch (err: any) {
      setError(err.message);
      setQuestionToDelete(null);
    }
  };

  const handleExportCSV = () => {
    const dataToExport = filteredAndSortedQuestions.map(q => ({
      ID: q.id,
      Frage: q.questionText,
      Typ: q.type,
      Kategorie: q.category,
      Antwort_A: q.options[0],
      Antwort_B: q.options[1],
      Antwort_C: q.options[2],
      Antwort_D: q.options[3],
      Korrekter_Index: q.correctAnswerIndex,
      Erklaerung: q.explanation,
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Fragen");
    XLSX.writeFile(workbook, "fragen-export.csv", { bookType: "csv" });
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Fragenkatalog - DZKB Bayern e.V.", 14, 22);

    autoTable(doc, {
        startY: 30,
        head: [['ID', 'Frage', 'Kategorie', 'Korrekte Antwort']],
        body: filteredAndSortedQuestions.map(q => [
            q.id,
            q.questionText,
            q.category,
            q.options[q.correctAnswerIndex]
        ]),
        styles: { overflow: 'linebreak', cellWidth: 'wrap', font: 'helvetica', fontSize: 8 },
        headStyles: { fillColor: [11, 121, 208] },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 'auto' },
            2: { cellWidth: 30 },
            3: { cellWidth: 40 }
        }
    });

    doc.save('fragen-katalog.pdf');
  };

  const categories = useMemo(() => ['all', ...Array.from(new Set(allQuestions.map(q => q.category).filter(Boolean)))], [allQuestions]) as string[];

  const requestSort = (key: SortableKeys) => {
      let direction: SortDirection = 'asc';
      if (sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const filteredAndSortedQuestions = useMemo(() => {
    let questions = allQuestions.filter(q => {
      const matchesCategory = categoryFilter === 'all' || q.category === categoryFilter;
      const matchesSearch = searchTerm === '' || 
        q.questionText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        q.options.some(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesCategory && matchesSearch;
    });

    if (sortConfig.key !== null) {
      questions.sort((a, b) => {
          const aValue = String(a[sortConfig.key!] ?? '').toLowerCase();
          const bValue = String(b[sortConfig.key!] ?? '').toLowerCase();

          if (sortConfig.direction === 'asc') {
              return aValue.localeCompare(bValue);
          } else {
              return bValue.localeCompare(aValue);
          }
      });
    }

    return questions;
  }, [allQuestions, searchTerm, categoryFilter, sortConfig]);

  const SortIndicator = ({ columnKey }: { columnKey: SortableKeys }) => {
    if (sortConfig.key !== columnKey) return <span className="ml-1 text-gray-300">↕</span>;
    if (sortConfig.direction === 'asc') return <span className="ml-1 text-[#0B79D0]">▲</span>;
    return <span className="ml-1 text-[#0B79D0]">▼</span>;
  };

  return (
    <div className="w-full min-h-screen bg-slate-100">
      {/* Header */}
      <header className="bg-[#0B79D0] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Admin Dashboard</h1>
          <button onClick={onLogout} className="bg-white text-[#0B79D0] font-bold py-2 px-5 rounded-lg hover:bg-slate-100 transition-colors">
            Sign Out
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Import/Export Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl shadow-lg">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Import</h2>
            <p className="text-sm text-gray-600 mb-4">Laden Sie eine Datei (PDF, DOCX, XLSX, etc.) hoch, um automatisch Fragen zu importieren.</p>
            <div className="flex items-center space-x-4">
              <input type="file" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            </div>
            {file && <button onClick={handleAnalyzeAndImport} disabled={analyzing} className="mt-4 w-full bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
              {analyzing ? 'Importiere...' : `"${file.name}" importieren`}
            </button>}
             {analyzing && <div className="mt-4 w-full">
                <div className="flex justify-between mb-1">
                    <span className="text-base font-medium text-slate-700">{analysisStatusMessage}</span>
                    <span className="text-sm font-medium text-[#0B79D0]">{analysisProgress}%</span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5"><div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${analysisProgress}%` }}></div></div>
              </div>}
          </div>
          <div className="bg-white p-6 rounded-xl shadow-lg">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Export</h2>
            <p className="text-sm text-gray-600 mb-4">Wählen Sie ein Format, um den aktuellen Fragenkatalog zu exportieren.</p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button onClick={handleExportCSV} className="flex-1 bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors">
                CSV Export
                </button>
                <button onClick={handleExportPDF} className="flex-1 bg-orange-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-orange-600 transition-colors">
                PDF Katalog
                </button>
            </div>
          </div>
        </div>

        {/* Question Management Table */}
        <div className="bg-white p-6 rounded-xl shadow-lg">
          <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
            <h2 className="text-xl font-bold text-gray-800">Fragen verwalten ({filteredAndSortedQuestions.length})</h2>
            <div className="flex items-center gap-4 w-full md:w-auto">
              <input type="text" placeholder="Suche..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-auto bg-white text-gray-900"/>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="p-2 border rounded-lg bg-white text-gray-900">
                {categories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'Alle Kategorien' : cat}</option>)}
              </select>
              <button onClick={() => handleOpenEditModal()} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 transition-colors whitespace-nowrap">+ Neue Frage</button>
            </div>
          </div>

          {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
          {successMessage && <p className="text-green-600 font-semibold mb-4">{successMessage}</p>}

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2">ID</th>
                   <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('questionText')}>
                      <div className="flex items-center">Frage <SortIndicator columnKey="questionText" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('type')}>
                      <div className="flex items-center">Typ <SortIndicator columnKey="type" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('category')}>
                      <div className="flex items-center">Kategorie <SortIndicator columnKey="category" /></div>
                    </th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {isLoadingQuestions ? (<tr><td colSpan={5} className="text-center p-4">Lade Fragen...</td></tr>) 
                : filteredAndSortedQuestions.map(q => (
                  <tr key={q.id} className="border-b hover:bg-slate-50 text-gray-800">
                    <td className="p-2 font-mono text-sm">{q.id}</td>
                    <td className="p-2 max-w-md truncate">{q.questionText}</td>
                    <td className="p-2"><span className="bg-blue-100 text-[#0B79D0] text-xs font-medium px-2.5 py-0.5 rounded-full">{q.type || 'N/A'}</span></td>
                    <td className="p-2">{q.category || 'N/A'}</td>
                    <td className="p-2 flex gap-4">
                      <button onClick={() => handleOpenEditModal(q)} className="text-[#0B79D0] font-semibold">Edit</button>
                      <button onClick={() => handleDeleteRequest(q)} className="text-red-500 font-semibold">Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {isEditModalOpen && editingQuestion && (
        <EditQuestionModal
          question={editingQuestion}
          isOpen={isEditModalOpen}
          onClose={handleCloseEditModal}
          onSave={handleSaveQuestion}
        />
      )}

      {questionToDelete && (
        <DeleteConfirmationModal
            isOpen={!!questionToDelete}
            onClose={() => setQuestionToDelete(null)}
            onConfirm={handleDeleteConfirmed}
            question={questionToDelete}
        />
      )}
    </div>
  );
};


// Modal Component
interface EditQuestionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (question: Question) => void;
  question: Question;
}

const EditQuestionModal: React.FC<EditQuestionModalProps> = ({ isOpen, onClose, onSave, question }) => {
  const [editedQuestion, setEditedQuestion] = useState<Question>(question);

  useEffect(() => {
    setEditedQuestion(question);
  }, [question]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedQuestion(prev => ({...prev, [name]: value}));
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...editedQuestion.options];
    newOptions[index] = value;
    setEditedQuestion(prev => ({...prev, options: newOptions}));
  };

  const handleCorrectAnswerChange = (index: number) => {
    setEditedQuestion(prev => ({...prev, correctAnswerIndex: index}));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-6 text-gray-800">{editedQuestion.id ? 'Frage bearbeiten' : 'Neue Frage erstellen'}</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Fragetext</label>
            <textarea name="questionText" value={editedQuestion.questionText} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={4}/>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Kategorie</label>
              <input type="text" name="category" value={editedQuestion.category || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900"/>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700">Typ</label>
              <select name="type" value={editedQuestion.type || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                  <option value="Single Choice">Single Choice</option>
                  <option value="Multiple Choice">Multiple Choice</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Antworten (die erste ist A, die zweite B, usw.)</label>
            {editedQuestion.options.map((opt, index) => (
              <div key={index} className="flex items-center mt-2">
                <input type="radio" name="correctAnswer" checked={editedQuestion.correctAnswerIndex === index} onChange={() => handleCorrectAnswerChange(index)} className="mr-2 h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"/>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(index, e.target.value)} className="w-full p-2 border rounded bg-gray-50 text-gray-900"/>
              </div>
            ))}
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Erklärung</label>
            <textarea name="explanation" value={editedQuestion.explanation} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={3}/>
          </div>
        </div>
        <div className="flex justify-end gap-4 mt-8">
          <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">Abbrechen</button>
          <button onClick={() => onSave(editedQuestion)} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4]">Speichern</button>
        </div>
      </div>
    </div>
  );
};

interface DeleteConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    question: Question;
}

const DeleteConfirmationModal: React.FC<DeleteConfirmationModalProps> = ({ isOpen, onClose, onConfirm, question }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 text-gray-800">Löschen bestätigen</h2>
                <p className="text-gray-600 mb-6">Sind Sie sicher, dass Sie die folgende Frage endgültig löschen möchten?</p>
                <div className="bg-slate-50 border border-slate-200 p-4 rounded-lg mb-6">
                    <p className="font-semibold text-gray-700 truncate">{question.questionText}</p>
                </div>
                <div className="flex justify-end gap-4">
                    <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">
                        Abbrechen
                    </button>
                    <button onClick={onConfirm} className="bg-red-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-red-700">
                        Löschen
                    </button>
                </div>
            </div>
        </div>
    );
};


