export default AdminPanel;

import { GoogleGenAI, Type } from "@google/genai";
import { Question } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const DEFAULT_PROMPT_TEMPLATE = `Erstelle ein Multiple-Choice-Quiz auf Deutsch mit {numQuestions} Fragen zum Thema "{topic}". Jede Frage sollte 4 Antwortmöglichkeiten haben, von denen nur eine richtig ist. Gib für jede Frage auch eine kurze Erklärung für die richtige Antwort und eine passende Kategorie, die sich auf das Thema "{topic}" bezieht. Für das Feld 'type' verwende ausschließlich den Wert 'Single'. Die Fragen sollten für Studenten geeignet sein, die sich auf eine Abschlussprüfung vorbereiten. Die Schwierigkeit sollte angemessen sein. Gib die Antwort ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht. Füge keine Markdown-Formatierung oder andere Texte außerhalb des JSON-Objekts hinzu.`;

const questionSchema = {
    type: Type.OBJECT,
    properties: {
      questionText: { type: Type.STRING },
      options: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        minItems: 4,
        maxItems: 4,
      },
