/**
 * Speichert ein Array von Fragen in der Supabase-Datenbank.
 * @param questions Ein Array von Question-Objekten.
 */
export const saveQuestions = async (questions: Omit<Question, 'id' | 'created_at'>[]): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { error } = await supabase
    .from('questions')
    .insert(questions);

  if (error) {
    console.error('Fehler beim Speichern der Fragen in Supabase:', error);
    throw new Error('Fragen konnten nicht in der Datenbank gespeichert werden.');
  }
};


/**
 * Holt eine zufällige Anzahl von Fragen für einen bestimmten Verband aus der Supabase-Datenbank.
 * @param count Die Anzahl der zufälligen Fragen, die abgerufen werden sollen.
 * @param verband Der Verband ('DZKB' oder 'ProHunde'), nach dem gefiltert werden soll.
 * @returns Ein Promise, das zu einem Array von Question-Objekten aufgelöst wird.
 */
export const fetchRandomQuestions = async (count: number, verband: 'DZKB' | 'ProHunde'): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .eq('verband', verband);

    if (error) {
        console.error('Fehler beim Abrufen der Fragen aus Supabase:', error);
        throw new Error('Fragen konnten nicht aus der Datenbank geladen werden.');
    }

    if (!data || data.length === 0) {
        throw new Error(`Keine Fragen für den Verband '${verband}' in der Datenbank gefunden.`);
    }

    // Mische das Array und wähle die ersten 'count' Elemente aus.
    const shuffled = data.sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count) as Question[];
};

/**
 * Holt alle Fragen aus der Datenbank.
 */
export const fetchAllQuestions = async (): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .order('id', { ascending: true });

    if (error) {
        console.error('Fehler beim Abrufen aller Fragen:', error);
        throw new Error('Fragen konnten nicht geladen werden.');
    }
    return data as Question[];
};

/**
 * Erstellt eine neue Frage in der Datenbank.
 */
export const createQuestion = async (question: Omit<Question, 'id' | 'created_at'>): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .insert([question])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen der Frage:', error);
        throw new Error('Frage konnte nicht erstellt werden.');
    }
    return data as Question;
};


/**
 * Aktualisiert eine bestehende Frage in der Datenbank.
 */
export const updateQuestion = async (question: Question): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (!question.id) throw new Error("Frage benötigt eine ID zum Aktualisieren.");

    const { id, created_at, ...updateData } = question;

    const { data, error } = await supabase
        .from('questions')
        .update(updateData)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren der Frage:', error);
        throw new Error('Frage konnte nicht aktualisiert werden.');
    }
    return data as Question;
};

/**
 * Löscht eine Frage aus der Datenbank.
 */
export const deleteQuestion = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .delete()
        .eq('id', id)
        .select();

    if (error) {
        console.error('Fehler beim Löschen der Frage:', error);
        throw new Error('Frage konnte nicht gelöscht werden.');
    }

    // Wenn RLS den Löschvorgang verhindert, ist der Fehler 'null', aber es werden keine Daten zurückgegeben.
    // Wir prüfen, ob der Löschvorgang tatsächlich erfolgreich war.
    if (!data || data.length === 0) {
      console.error('Löschen der Frage fehlgeschlagen: Zeile nicht gefunden oder keine Berechtigung.');
      throw new Error('Frage konnte nicht gelöscht werden. Möglicherweise fehlt die Berechtigung oder die Frage existiert nicht mehr.');
    }
};

/**
 * Löscht mehrere Fragen auf einmal aus der Datenbank.
 * @param ids Ein Array von IDs der zu löschenden Fragen.
 */
export const deleteMultipleQuestions = async (ids: number[]): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (ids.length === 0) return;

    const { error } = await supabase
        .from('questions')
        .delete()
        .in('id', ids);

    if (error) {
        console.error('Fehler beim Löschen mehrerer Fragen:', error);
        throw new Error('Die ausgewählten Fragen konnten nicht gelöscht werden.');
    }
};

import React, { useState, useCallback } from 'react';
import { Question } from './types';
import TopicSelector from './components/TopicSelector';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Loader from './components/Loader';
import Login from './components/Login';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';
import { generateQuiz } from './services/geminiService';
import { fetchRandomQuestions } from './services/supabaseService';

type GameState = 'config' | 'quiz' | 'results';
type View = 'user' | 'admin_login' | 'admin_panel';
export type QuizSource = 'ai' | 'db';
export type Verband = 'DZKB' | 'ProHunde';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [gameState, setGameState] = useState<GameState>('config');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<View>('user');

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleStartQuiz = useCallback(async (topic: string, numQuestions: number, source: QuizSource, verband: Verband) => {
    setIsLoading(true);
    setError(null);
    try {
      let fetchedQuestions: Question[];
      if (source === 'ai') {
        fetchedQuestions = await generateQuiz(topic, numQuestions);
      } else {
        fetchedQuestions = await fetchRandomQuestions(numQuestions, verband);
      }
      setQuestions(fetchedQuestions);
      setUserAnswers(new Array(fetchedQuestions.length).fill(null));
      setGameState('quiz');
    } catch (err: any) {
      setError(err.message || 'Fehler beim Abrufen des Quiz. Bitte versuchen Sie es später erneut.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleAnswerSelect = (questionIndex: number, answerIndex: number) => {
    setUserAnswers(prev => {
      const newAnswers = [...prev];
      newAnswers[questionIndex] = answerIndex;
      return newAnswers;
    });
  };

  const handleSubmitQuiz = () => {
    setGameState('results');
  };

  const handleRestart = () => {
    setGameState('config');
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderUserContent = () => {
    if (isLoading) {
      return <Loader message="Quiz wird geladen... Bitte haben Sie einen Moment Geduld." />;
    }

    if (error) {
        return (
            <div className="text-center p-8 bg-white rounded-lg shadow-xl">
                <h2 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h2>
                <p className="text-slate-700 mb-6">{error}</p>
                <button
                    onClick={handleRestart}
                    className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors duration-300"
                >
                    Zurück zum Start
                </button>
            </div>
        );
    }

    switch (gameState) {
      case 'quiz':
        return <Quiz 
          questions={questions} 
          userAnswers={userAnswers} 
          onAnswerSelect={handleAnswerSelect} 
          onSubmit={handleSubmitQuiz} 
        />;
      case 'results':
        return <Results 
          questions={questions} 
          userAnswers={userAnswers} 
          onRestart={handleRestart} 
        />;
      case 'config':
      default:
        return <TopicSelector onStartQuiz={handleStartQuiz} />;
    }
  };

  if (view === 'admin_login') {
    return (
      <div className="min-h-screen font-sans flex items-center justify-center p-4 bg-gradient-to-b from-slate-800 to-slate-900">
        <AdminLogin onLoginSuccess={() => setView('admin_panel')} onCancel={() => setView('user')} />
      </div>
    );
  }

  if (view === 'admin_panel') {
     return (
      <div className="min-h-screen font-sans flex flex-col items-center p-4 bg-slate-100">
        <AdminPanel onLogout={() => setView('user')} />
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
       <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
        <Login onLoginSuccess={handleLoginSuccess} />
         <footer className="w-full max-w-4xl mx-auto text-center py-4 absolute bottom-0">
          <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors">
            Admin
          </button>
        </footer>
      </div>
    );
  }

  return (
    <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
      <header className="w-full max-w-4xl mx-auto text-center mb-6">
        <h1 className="text-4xl md:text-5xl font-extrabold text-white drop-shadow-lg">DZKB Bayern e.V. Prüfungstrainer</h1>
        <p className="text-blue-100 mt-2 text-lg">Teste dein Wissen.</p>
      </header>
      <main className="w-full max-w-4xl mx-auto flex justify-center">
        {renderUserContent()}
      </main>
       <footer className="w-full max-w-4xl mx-auto text-center mt-8 text-blue-200 text-sm">
        <p>Unterstützt durch die Gemini API</p>
         <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors mt-2">
            Admin
          </button>
      </footer>
    </div>
  );
};

export default App;

