                const options: string[] = [];
                for (let i = 1; i <= 8; i++) {
                    const answer = row[`Antwort ${i}`];
                    if (answer && String(answer).trim()) {
                        options.push(decodeHtml(String(answer)));
                    }
                }

                if (options.length === 0) continue;

                let correctAnswerIndex = -1;
                for (let i = 1; i <= options.length; i++) {
                     if (String(row[`Antwort ${i} korrekt`]).toLowerCase() === 'richtig') {
                        correctAnswerIndex = i - 1;
                        break;
                    }
                }

                if (correctAnswerIndex === -1) continue;

                const question: Omit<Question, 'id' | 'created_at'> = {
                    questionText,
                    options,
                    correctAnswerIndex,
                    category: row['Kategorie'] || 'Allgemein',
                    type: String(row['Fragetyp']).startsWith('Single') ? 'Single' : 'Multi',
                    verband: uploadVerband,
                };
                allParsedQuestions.push(question);
            }
             setAnalysisProgress(90);
        } else {
            setAnalysisStatusMessage('Datei wird gelesen...');
            let textContent = '';
            const fileType = file.type;

            if (fileType === 'text/plain') {
                textContent = await file.text();
            } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
                const arrayBuffer = await file.arrayBuffer();
                const pdf = await pdfjs.getDocument(arrayBuffer).promise;
                textContent = (await Promise.all(Array.from({ length: pdf.numPages }, (_, i) => pdf.getPage(i + 1).then(page => page.getTextContent()))))
                    .map(content => content.items.map((item: any) => item.str).join(' ')).join('\n\n');
            } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
                const arrayBuffer = await file.arrayBuffer();
                const result = await mammoth.extractRawText({ arrayBuffer });
                textContent = result.value;
            } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
                const arrayBuffer = await file.arrayBuffer();
                const workbook = XLSX.read(arrayBuffer, { type: 'array' });
                textContent = workbook.SheetNames.map(sheetName => XLSX.utils.sheet_to_csv(workbook.Sheets[sheetName])).join('\n');
            } else {
                throw new Error(`Dateityp wird nicht unterstützt. Bitte TXT, CSV, PDF, DOCX oder XLSX verwenden.`);
            }

            setAnalysisProgress(15);
            setAnalysisStatusMessage('Text wird extrahiert...');

            if (!textContent.trim()) throw new Error('Kein Text in der Datei gefunden.');

            const handleProgressUpdate = (message: string) => {
                setAnalysisStatusMessage(message);
                setAnalysisProgress(prev => Math.min(90, prev + 10));
            };
            const extractedQuestions = await structureAndExtractQuestions(textContent, handleProgressUpdate);
            allParsedQuestions = extractedQuestions.map(q => ({ ...q, verband: uploadVerband }));
        }

        if (allParsedQuestions.length === 0) {
          throw new Error("Es konnten keine Fragen aus der Datei extrahiert werden. Überprüfen Sie das Format oder den Inhalt.");
        }

        setAnalysisProgress(95);
        setAnalysisStatusMessage('Fragen werden in die Datenbank importiert...');
        await saveQuestions(allParsedQuestions);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Import erfolgreich abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 1000)); 

        showSuccessMessage(`${allParsedQuestions.length} Fragen erfolgreich importiert!`);
        fetchQuestions();
        setFile(null);
        setUploadVerband('');

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file, fetchQuestions, uploadVerband]);

  // Question Management Logic
  const handleOpenEditModal = (question?: Question) => {
    setEditingQuestion(question || { questionText: '', options: ['', '', '', ''], correctAnswerIndex: 0, category: 'Hundeführerschein', type: 'Single', verband: 'DZKB' });
    setIsEditModalOpen(true);
  };

  const handleCloseEditModal = () => {
    setIsEditModalOpen(false);
    setEditingQuestion(null);
  };

  const handleSaveQuestion = async (questionToSave: Question) => {
    try {
      if (questionToSave.id) {
        await updateQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich aktualisiert.');
      } else {
        await createQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich erstellt.');
      }
      fetchQuestions();
      handleCloseEditModal();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleDeleteRequest = (question: Question) => {
    setQuestionToDelete(question);
  };

  const handleDeleteConfirmed = async () => {
    if (!questionToDelete) return;
    try {
      await deleteQuestion(questionToDelete.id!);
      showSuccessMessage('Frage erfolgreich gelöscht.');
      setQuestionToDelete(null);
      fetchQuestions();
    } catch (err: any) {
      setError(err.message);
      setQuestionToDelete(null);
    }
  };

  const handleBulkDeleteConfirmed = async () => {
    try {
      await deleteMultipleQuestions(Array.from(selectedQuestionIds));
      showSuccessMessage(`${selectedQuestionIds.size} Fragen erfolgreich gelöscht.`);
      setSelectedQuestionIds(new Set());
      setIsBulkDeleteModalOpen(false);
      fetchQuestions();
    } catch (err: any) {
      setError(err.message);
      setIsBulkDeleteModalOpen(false);
    }
  };

  const formatQuestionType = (type?: string | null): string => {
    if (type === 'Single Choice') return 'Single';
    if (type === 'Multiple Choice') return 'Multi';
    return type || 'N/A';
  };

  const handleExportCSV = () => {
    const dataToExport = filteredAndSortedQuestions.map((q, index) => ({
      'Nr.': index + 1,
      Frage: q.questionText,
      Typ: formatQuestionType(q.type),
      Kategorie: q.category,
      Verband: q.verband,
      Antwort_A: q.options[0],
      Antwort_B: q.options[1],
      Antwort_C: q.options[2],
      Antwort_D: q.options[3],
      Korrekter_Index: q.correctAnswerIndex,
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Fragen");
    XLSX.writeFile(workbook, "fragen-export.csv", { bookType: "csv" });
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Fragenkatalog - DZKB Bayern e.V.", 14, 22);

    autoTable(doc, {
        startY: 30,
        head: [['Nr.', 'Frage', 'Kategorie', 'Verband', 'Korrekte Antwort']],
        body: filteredAndSortedQuestions.map((q, index) => [
            index + 1,
            q.questionText,
            q.category,
            q.verband,
            q.options[q.correctAnswerIndex]
        ]),
        styles: { overflow: 'linebreak', cellWidth: 'wrap', font: 'helvetica', fontSize: 8 },
        headStyles: { fillColor: [11, 121, 208] },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 'auto' },
            2: { cellWidth: 30 },
            3: { cellWidth: 20 },
            4: { cellWidth: 40 }
        }
    });

    doc.save('fragen-katalog.pdf');
  };

  const categories = useMemo(() => ['all', ...Array.from(new Set(allQuestions.map(q => q.category).filter(Boolean)))], [allQuestions]) as string[];

  const requestSort = (key: SortableKeys) => {
      let direction: SortDirection = 'asc';
      if (sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const filteredAndSortedQuestions = useMemo(() => {
    let questions = allQuestions.filter(q => {
      const matchesCategory = categoryFilter === 'all' || q.category === categoryFilter;
      const matchesVerband = verbandFilter === 'all' || q.verband === verbandFilter;
      const matchesSearch = searchTerm === '' || 
        q.questionText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        q.options.some(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesCategory && matchesSearch && matchesVerband;
    });

    if (sortConfig.key !== null) {
      questions.sort((a, b) => {
          const aValue = String(a[sortConfig.key!] ?? '').toLowerCase();
          const bValue = String(b[sortConfig.key!] ?? '').toLowerCase();

          if (sortConfig.direction === 'asc') {
              return aValue.localeCompare(bValue);
          } else {
              return bValue.localeCompare(aValue);
          }
      });
    }

    return questions;
  }, [allQuestions, searchTerm, categoryFilter, verbandFilter, sortConfig]);

  const handleSelectOne = (questionId: number) => {
    setSelectedQuestionIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(questionId)) {
        newSet.delete(questionId);
      } else {
        newSet.add(questionId);
      }
      return newSet;
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      const allFilteredIds = filteredAndSortedQuestions.map(q => q.id!);
      setSelectedQuestionIds(new Set(allFilteredIds));
    } else {
      setSelectedQuestionIds(new Set());
    }
  };

  useEffect(() => {
    if (selectAllCheckboxRef.current) {
      const numSelected = selectedQuestionIds.size;
      const numFiltered = filteredAndSortedQuestions.length;
      selectAllCheckboxRef.current.checked = numSelected === numFiltered && numFiltered > 0;
      selectAllCheckboxRef.current.indeterminate = numSelected > 0 && numSelected < numFiltered;
    }
  }, [selectedQuestionIds, filteredAndSortedQuestions]);

  const SortIndicator = ({ columnKey }: { columnKey: SortableKeys }) => {
    if (sortConfig.key !== columnKey) return <span className="ml-1 text-gray-300">↕</span>;
    if (sortConfig.direction === 'asc') return <span className="ml-1 text-[#0B79D0]">▲</span>;
    return <span className="ml-1 text-[#0B79D0]">▼</span>;
  };

  return (
    <div className="w-full min-h-screen bg-slate-100">
      {/* Header */}
      <header className="bg-[#0B79D0] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Admin Dashboard</h1>
          <button onClick={onLogout} className="bg-white text-[#0B79D0] font-bold py-2 px-5 rounded-lg hover:bg-slate-100 transition-colors">
            Sign Out
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Import/Export Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl shadow-lg">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Import</h2>
            <p className="text-sm text-gray-600 mb-4">Laden Sie eine Datei (CSV, PDF, DOCX, etc.) hoch und wählen Sie den zugehörigen Verband.</p>
            <div className="flex items-center space-x-4">
              <input type="file" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            </div>
             {file && (
              <div className="mt-4">
                <p className="text-sm font-medium text-gray-700 mb-2">Verband für Import auswählen:</p>
                <div className="flex gap-4">
                    {(['DZKB', 'ProHunde'] as const).map(v => (
                        <label key={v} className="flex items-center">
                            <input
                                type="radio"
                                name="uploadVerband"
                                value={v}
                                checked={uploadVerband === v}
                                onChange={() => setUploadVerband(v)}
                                className="h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"
                            />
                            <span className="ml-2 text-gray-700">{v}</span>
                        </label>
                    ))}
                </div>
              </div>
            )}
            {file && <button onClick={handleAnalyzeAndImport} disabled={analyzing || !uploadVerband} className="mt-4 w-full bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
              {analyzing ? 'Analysiere...' : `"${file.name}" importieren`}
            </button>}
             {analyzing && <div className="mt-4 w-full">
                <div className="flex justify-between mb-1">
                    <span className="text-base font-medium text-slate-700">{analysisStatusMessage}</span>
                    <span className="text-sm font-medium text-[#0B79D0]">{analysisProgress}%</span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5"><div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${analysisProgress}%` }}></div></div>
              </div>}
          </div>
          <div className="bg-white p-6 rounded-xl shadow-lg">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Export</h2>
            <p className="text-sm text-gray-600 mb-4">Wählen Sie ein Format, um den aktuellen Fragenkatalog zu exportieren.</p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button onClick={handleExportCSV} className="flex-1 bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors">
                CSV Export
                </button>
                <button onClick={handleExportPDF} className="flex-1 bg-orange-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-orange-600 transition-colors">
                PDF Katalog
                </button>
            </div>
          </div>
        </div>

        {/* Question Management Table */}
        <div className="bg-white p-6 rounded-xl shadow-lg">
          <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
            <h2 className="text-xl font-bold text-gray-800">Fragen verwalten ({filteredAndSortedQuestions.length})</h2>
            <div className="flex items-center gap-4 w-full md:w-auto flex-wrap">
              <input type="text" placeholder="Suche..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full md:w-auto bg-white text-gray-900"/>
              <select value={verbandFilter} onChange={e => setVerbandFilter(e.target.value as 'all' | Verband)} className="p-2 border rounded-lg bg-white text-gray-900">
                  <option value="all">Alle Verbände</option>
                  <option value="DZKB">DZKB</option>
                  <option value="ProHunde">ProHunde</option>
              </select>
              <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="p-2 border rounded-lg bg-white text-gray-900">
                {categories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'Alle Kategorien' : cat}</option>)}
              </select>
              {selectedQuestionIds.size > 0 && (
                <button onClick={() => setIsBulkDeleteModalOpen(true)} className="bg-red-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-red-700 transition-colors whitespace-nowrap">
                  {selectedQuestionIds.size} Ausgewählte löschen
                </button>
              )}
              <button onClick={() => handleOpenEditModal()} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 transition-colors whitespace-nowrap">+ Neue Frage</button>
            </div>
          </div>

          {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
          {successMessage && <p className="text-green-600 font-semibold mb-4">{successMessage}</p>}

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2 w-12">
                    <input
                      type="checkbox"
                      ref={selectAllCheckboxRef}
                      onChange={handleSelectAll}
                      className="h-4 w-4 rounded border-gray-300 text-[#0B79D0] focus:ring-[#0B79D0]"
                     />
                  </th>
                  <th className="p-2">Nr.</th>
                   <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('questionText')}>
                      <div className="flex items-center">Frage <SortIndicator columnKey="questionText" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('type')}>
                      <div className="flex items-center">Typ <SortIndicator columnKey="type" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('category')}>
                      <div className="flex items-center">Kategorie <SortIndicator columnKey="category" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('verband')}>
                      <div className="flex items-center">Verband <SortIndicator columnKey="verband" /></div>
                    </th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {isLoadingQuestions ? (<tr><td colSpan={7} className="text-center p-4">Lade Fragen...</td></tr>) 
                : filteredAndSortedQuestions.map((q, index) => (
                  <tr key={q.id} className={`border-b text-gray-800 ${selectedQuestionIds.has(q.id!) ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                    <td className="p-2">
                       <input
                          type="checkbox"
                          checked={selectedQuestionIds.has(q.id!)}
                          onChange={() => handleSelectOne(q.id!)}
                          className="h-4 w-4 rounded border-gray-300 text-[#0B79D0] focus:ring-[#0B79D0]"
                        />
                    </td>
                    <td className="p-2 text-center text-sm text-gray-500">{index + 1}</td>
                    <td className="p-2 max-w-md truncate">{q.questionText}</td>
                    <td className="p-2"><span className="bg-blue-100 text-[#0B79D0] text-xs font-medium px-2.5 py-0.5 rounded-full">{formatQuestionType(q.type)}</span></td>
                    <td className="p-2">{q.category || 'N/A'}</td>
                    <td className="p-2">{q.verband || 'N/A'}</td>
                    <td className="p-2 flex gap-4">
                      <button onClick={() => handleOpenEditModal(q)} className="text-[#0B79D0] font-semibold">Edit</button>
                      <button onClick={() => handleDeleteRequest(q)} className="text-red-500 font-semibold">Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {isEditModalOpen && editingQuestion && (
        <EditQuestionModal
          question={editingQuestion}
          isOpen={isEditModalOpen}
          onClose={handleCloseEditModal}
          onSave={handleSaveQuestion}
        />
      )}

      {questionToDelete && (
        <DeleteConfirmationModal
            isOpen={!!questionToDelete}
            onClose={() => setQuestionToDelete(null)}
            onConfirm={handleDeleteConfirmed}
            question={questionToDelete}
        />
      )}

      {isBulkDeleteModalOpen && (
        <BulkDeleteConfirmationModal
          isOpen={isBulkDeleteModalOpen}
          onClose={() => setIsBulkDeleteModalOpen(false)}
          onConfirm={handleBulkDeleteConfirmed}
          count={selectedQuestionIds.size}
        />
      )}
    </div>
  );
};


// Modal Component
interface EditQuestionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (question: Question) => void;
  question: Question;
}

const EditQuestionModal: React.FC<EditQuestionModalProps> = ({ isOpen, onClose, onSave, question }) => {
  const [editedQuestion, setEditedQuestion] = useState<Question>(question);

  useEffect(() => {
    setEditedQuestion(question);
  }, [question]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedQuestion(prev => ({...prev, [name]: value}));
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...editedQuestion.options];
    newOptions[index] = value;
    setEditedQuestion(prev => ({...prev, options: newOptions}));
  };

  const handleCorrectAnswerChange = (index: number) => {
    setEditedQuestion(prev => ({...prev, correctAnswerIndex: index}));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-6 text-gray-800">{editedQuestion.id ? 'Frage bearbeiten' : 'Neue Frage erstellen'}</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Fragetext</label>
            <textarea name="questionText" value={editedQuestion.questionText} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={4}/>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Kategorie</label>
              <input type="text" name="category" value={editedQuestion.category || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900"/>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700">Typ</label>
              <select name="type" value={editedQuestion.type || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                  <option value="Single">Single</option>
                  <option value="Multi">Multi</option>
              </select>
            </div>
             <div>
                <label className="block text-sm font-medium text-gray-700">Verband</label>
                <select name="verband" value={editedQuestion.verband || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                    <option value="DZKB">DZKB</option>
                    <option value="ProHunde">ProHunde</option>
                </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Antworten (die erste ist A, die zweite B, usw.)</label>
            {editedQuestion.options.map((opt, index) => (
              <div key={index} className="flex items-center mt-2">
                <input type="radio" name="correctAnswer" checked={editedQuestion.correctAnswerIndex === index} onChange={() => handleCorrectAnswerChange(index)} className="mr-2 h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"/>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(index, e.target.value)} className="w-full p-2 border rounded bg-gray-50 text-gray-900"/>
              </div>
            ))}
          </div>
        </div>
        <div className="flex justify-end gap-4 mt-8">
          <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">Abbrechen</button>
          <button onClick={() => onSave(editedQuestion)} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4]">Speichern</button>
        </div>
      </div>
    </div>
  );
};

interface DeleteConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    question: Question;
}

const DeleteConfirmationModal: React.FC<DeleteConfirmationModalProps> = ({ isOpen, onClose, onConfirm, question }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 text-gray-800">Löschen bestätigen</h2>
                <p className="text-gray-600 mb-6">Sind Sie sicher, dass Sie die folgende Frage endgültig löschen möchten?</p>
                <div className="bg-slate-50 border border-slate-200 p-4 rounded-lg mb-6">
                    <p className="font-semibold text-gray-700 truncate">{question.questionText}</p>
                </div>
                <div className="flex justify-end gap-4">
                    <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">
                        Abbrechen
                    </button>
                    <button onClick={onConfirm} className="bg-red-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-red-700">
                        Löschen
                    </button>
                </div>
            </div>
        </div>
    );
};

interface BulkDeleteConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    count: number;
}

const BulkDeleteConfirmationModal: React.FC<BulkDeleteConfirmationModalProps> = ({ isOpen, onClose, onConfirm, count }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 text-gray-800">Löschen bestätigen</h2>
                <p className="text-gray-600 mb-6">Sind Sie sicher, dass Sie die <span className="font-bold">{count}</span> ausgewählten Fragen endgültig löschen möchten?</p>
                <div className="flex justify-end gap-4">
                    <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">
                        Abbrechen
                    </button>
                    <button onClick={onConfirm} className="bg-red-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-red-700">
                        Löschen
                    </button>
                </div>
            </div>
        </div>
    );
};


export default AdminPanel;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { structureAndExtractQuestions } from '../services/geminiService';
import { saveQuestions, fetchAllQuestions, deleteQuestion, updateQuestion, createQuestion, deleteMultipleQuestions } from '../services/supabaseService';
import { Question } from '../types';
import { Verband } from '../App';
import * as XLSX from 'xlsx';
import mammoth from 'mammoth';
import * as pdfjs from 'pdfjs-dist';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// Configure the PDF.js worker to enable client-side PDF processing.
pdfjs.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@4.4.178/build/pdf.worker.mjs`;

interface AdminPanelProps {
  onLogout: () => void;
}

type SortDirection = 'asc' | 'desc';
type SortableKeys = 'questionText' | 'type' | 'category' | 'verband';

interface SortConfig {
    key: SortableKeys | null;
    direction: SortDirection;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onLogout }) => {
  // State for file import
  const [file, setFile] = useState<File | null>(null);
  const [uploadVerband, setUploadVerband] = useState<Verband | ''>('');
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisStatusMessage, setAnalysisStatusMessage] = useState('');

  // State for question management
  const [allQuestions, setAllQuestions] = useState<Question[]>([]);
  const [isLoadingQuestions, setIsLoadingQuestions] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [verbandFilter, setVerbandFilter] = useState<'all' | Verband>('all');
  const [typeFilter, setTypeFilter] = useState<'all' | 'Single' | 'Multi'>('all');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: null, direction: 'asc' });
  const [selectedQuestionIds, setSelectedQuestionIds] = useState<Set<number>>(new Set());


  // State for modals
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingQuestion, setEditingQuestion] = useState<Question | null>(null);
  const [questionToDelete, setQuestionToDelete] = useState<Question | null>(null);
  const [isBulkDeleteModalOpen, setIsBulkDeleteModalOpen] = useState(false);


  // General state
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const selectAllCheckboxRef = useRef<HTMLInputElement>(null);

  const fetchQuestions = useCallback(async () => {
    setIsLoadingQuestions(true);
    try {
      const questions = await fetchAllQuestions();
      setAllQuestions(questions);
    } catch (err: any) {
      setError(err.message || "Fehler beim Laden der Fragen.");
    } finally {
      setIsLoadingQuestions(false);
    }
  }, []);

  useEffect(() => {
    fetchQuestions();
  }, [fetchQuestions]);

  const showSuccessMessage = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => setSuccessMessage(null), 3000);
  };

  const formatQuestionType = useCallback((type?: string | null): string => {
    if (type === 'Single Choice' || type === 'Single') return 'Single';
    if (type === 'Multiple Choice' || type === 'Multi') return 'Multi';
    return type || 'N/A';
  }, []);

  // File Upload and Analysis Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setSuccessMessage(null);
    }
  };

  const handleAnalyzeAndImport = useCallback(async () => {
    if (!file || !uploadVerband) return;

    setAnalyzing(true);
    setError(null);
    setSuccessMessage(null);
    setAnalysisProgress(0);

    try {
        setAnalysisProgress(5);

        let allParsedQuestions: Omit<Question, 'id' | 'created_at'>[] = [];
        const fileName = file.name.toLowerCase();
        const isCsv = file.type === 'text/csv' || fileName.endsWith('.csv');

        if (isCsv) {
            setAnalysisStatusMessage('Verarbeite CSV-Datei...');
            const textContent = await file.text();
            const cleanText = textContent.startsWith('\ufeff') ? textContent.substring(1) : textContent;

            const workbook = XLSX.read(cleanText, { type: 'string' });
            const sheetName = workbook.SheetNames[0];
            const jsonData = XLSX.utils.sheet_to_json<any>(workbook.Sheets[sheetName]);

            const decodeHtml = (html: string): string => {
                if (!html) return '';
                const txt = document.createElement("textarea");
                txt.innerHTML = html;
                return txt.value.replace(/<[^>]*>?/gm, '').trim();
            };

            for (const row of jsonData) {
                const questionText = row['Frage'] ? decodeHtml(row['Frage']) : null;
                if (!questionText) continue;

                const options: string[] = [];
                for (let i = 1; i <= 8; i++) {
                    const answer = row[`Antwort ${i}`];
                    if (answer && String(answer).trim()) {
                        options.push(decodeHtml(String(answer)));
                    }
                }

                if (options.length === 0) continue;

                let correctAnswerIndex = -1;
                for (let i = 1; i <= options.length; i++) {
                     if (String(row[`Antwort ${i} korrekt`]).toLowerCase() === 'richtig') {
                        correctAnswerIndex = i - 1;
                        break;
                    }
                }

                if (correctAnswerIndex === -1) continue;

                const question: Omit<Question, 'id' | 'created_at'> = {
                    questionText,
                    options,
                    correctAnswerIndex,
                    category: row['Kategorie'] || 'Allgemein',
                    type: String(row['Fragetyp']).startsWith('Single') ? 'Single' : 'Multi',
                    verband: uploadVerband,
                };
                allParsedQuestions.push(question);
            }
             setAnalysisProgress(90);
        } else {
            setAnalysisStatusMessage('Datei wird gelesen...');
            let textContent = '';
            const fileType = file.type;

            if (fileType === 'text/plain') {
                textContent = await file.text();
            } else if (fileType === 'application/pdf' || fileName.endsWith('.pdf')) {
                const arrayBuffer = await file.arrayBuffer();
                const pdf = await pdfjs.getDocument(arrayBuffer).promise;
                textContent = (await Promise.all(Array.from({ length: pdf.numPages }, (_, i) => pdf.getPage(i + 1).then(page => page.getTextContent()))))
                    .map(content => content.items.map((item: any) => item.str).join(' ')).join('\n\n');
            } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.endsWith('.docx')) {
                const arrayBuffer = await file.arrayBuffer();
                const result = await mammoth.extractRawText({ arrayBuffer });
                textContent = result.value;
            } else if (fileType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || fileName.endsWith('.xlsx')) {
                const arrayBuffer = await file.arrayBuffer();
                const workbook = XLSX.read(arrayBuffer, { type: 'array' });
                textContent = workbook.SheetNames.map(sheetName => XLSX.utils.sheet_to_csv(workbook.Sheets[sheetName])).join('\n');
            } else {
                throw new Error(`Dateityp wird nicht unterstützt. Bitte TXT, CSV, PDF, DOCX oder XLSX verwenden.`);
            }

            setAnalysisProgress(15);
            setAnalysisStatusMessage('Text wird extrahiert...');

            if (!textContent.trim()) throw new Error('Kein Text in der Datei gefunden.');

            const handleProgressUpdate = (message: string) => {
                setAnalysisStatusMessage(message);
                setAnalysisProgress(prev => Math.min(90, prev + 10));
            };
            const extractedQuestions = await structureAndExtractQuestions(textContent, handleProgressUpdate);
            allParsedQuestions = extractedQuestions.map(q => ({ ...q, verband: uploadVerband }));
        }

        if (allParsedQuestions.length === 0) {
          throw new Error("Es konnten keine Fragen aus der Datei extrahiert werden. Überprüfen Sie das Format oder den Inhalt.");
        }

        setAnalysisProgress(95);
        setAnalysisStatusMessage('Fragen werden in die Datenbank importiert...');
        await saveQuestions(allParsedQuestions);

        setAnalysisProgress(100);
        setAnalysisStatusMessage('Import erfolgreich abgeschlossen!');
        await new Promise(resolve => setTimeout(resolve, 1000)); 

        showSuccessMessage(`${allParsedQuestions.length} Fragen erfolgreich importiert!`);
        fetchQuestions();
        setFile(null);
        setUploadVerband('');

    } catch (err: any) {
        setError(err.message || "Ein unbekannter Fehler ist aufgetreten.");
    } finally {
        setAnalyzing(false);
        setAnalysisProgress(0);
        setAnalysisStatusMessage('');
    }
  }, [file, fetchQuestions, uploadVerband]);

  // Question Management Logic
  const handleOpenEditModal = (question?: Question) => {
    setEditingQuestion(question || { questionText: '', options: ['', '', '', ''], correctAnswerIndex: 0, category: 'Hundeführerschein', type: 'Single', verband: 'DZKB' });
    setIsEditModalOpen(true);
  };

  const handleCloseEditModal = () => {
    setIsEditModalOpen(false);
    setEditingQuestion(null);
  };

  const handleSaveQuestion = async (questionToSave: Question) => {
    try {
      if (questionToSave.id) {
        await updateQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich aktualisiert.');
      } else {
        await createQuestion(questionToSave);
        showSuccessMessage('Frage erfolgreich erstellt.');
      }
      fetchQuestions();
      handleCloseEditModal();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleDeleteRequest = (question: Question) => {
    setQuestionToDelete(question);
  };

  const handleDeleteConfirmed = async () => {
    if (!questionToDelete) return;
    try {
      await deleteQuestion(questionToDelete.id!);
      showSuccessMessage('Frage erfolgreich gelöscht.');
      setQuestionToDelete(null);
      fetchQuestions();
    } catch (err: any) {
      setError(err.message);
      setQuestionToDelete(null);
    }
  };

  const handleBulkDeleteConfirmed = async () => {
    try {
      await deleteMultipleQuestions(Array.from(selectedQuestionIds));
      showSuccessMessage(`${selectedQuestionIds.size} Fragen erfolgreich gelöscht.`);
      setSelectedQuestionIds(new Set());
      setIsBulkDeleteModalOpen(false);
      fetchQuestions();
    } catch (err: any) {
      setError(err.message);
      setIsBulkDeleteModalOpen(false);
    }
  };

  const handleExportCSV = () => {
    const dataToExport = filteredAndSortedQuestions.map((q, index) => ({
      'Nr.': index + 1,
      Frage: q.questionText,
      Typ: formatQuestionType(q.type),
      Kategorie: q.category,
      Verband: q.verband,
      Antwort_A: q.options[0],
      Antwort_B: q.options[1],
      Antwort_C: q.options[2],
      Antwort_D: q.options[3],
      Korrekter_Index: q.correctAnswerIndex,
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Fragen");
    XLSX.writeFile(workbook, "fragen-export.csv", { bookType: "csv" });
  };

  const handleExportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Fragenkatalog - DZKB Bayern e.V.", 14, 22);

    autoTable(doc, {
        startY: 30,
        head: [['Nr.', 'Frage', 'Kategorie', 'Verband', 'Korrekte Antwort']],
        body: filteredAndSortedQuestions.map((q, index) => [
            index + 1,
            q.questionText,
            q.category,
            q.verband,
            q.options[q.correctAnswerIndex]
        ]),
        styles: { overflow: 'linebreak', cellWidth: 'wrap', font: 'helvetica', fontSize: 8 },
        headStyles: { fillColor: [11, 121, 208] },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 'auto' },
            2: { cellWidth: 30 },
            3: { cellWidth: 20 },
            4: { cellWidth: 40 }
        }
    });

    doc.save('fragen-katalog.pdf');
  };

  const categories = useMemo(() => ['all', ...Array.from(new Set(allQuestions.map(q => q.category).filter(Boolean)))], [allQuestions]) as string[];

  const requestSort = (key: SortableKeys) => {
      let direction: SortDirection = 'asc';
      if (sortConfig.key === key && sortConfig.direction === 'asc') {
          direction = 'desc';
      }
      setSortConfig({ key, direction });
  };

  const filteredAndSortedQuestions = useMemo(() => {
    let questions = allQuestions.filter(q => {
      const matchesCategory = categoryFilter === 'all' || q.category === categoryFilter;
      const matchesVerband = verbandFilter === 'all' || q.verband === verbandFilter;
      const matchesType = typeFilter === 'all' || formatQuestionType(q.type) === typeFilter;
      const matchesSearch = searchTerm === '' || 
        q.questionText.toLowerCase().includes(searchTerm.toLowerCase()) ||
        q.options.some(opt => opt.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesCategory && matchesSearch && matchesVerband && matchesType;
    });

    if (sortConfig.key !== null) {
      questions.sort((a, b) => {
          const aValue = String(a[sortConfig.key!] ?? '').toLowerCase();
          const bValue = String(b[sortConfig.key!] ?? '').toLowerCase();

          if (sortConfig.direction === 'asc') {
              return aValue.localeCompare(bValue);
          } else {
              return bValue.localeCompare(aValue);
          }
      });
    }

    return questions;
  }, [allQuestions, searchTerm, categoryFilter, verbandFilter, typeFilter, sortConfig, formatQuestionType]);

  const handleSelectOne = (questionId: number) => {
    setSelectedQuestionIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(questionId)) {
        newSet.delete(questionId);
      } else {
        newSet.add(questionId);
      }
      return newSet;
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      const allFilteredIds = filteredAndSortedQuestions.map(q => q.id!);
      setSelectedQuestionIds(new Set(allFilteredIds));
    } else {
      setSelectedQuestionIds(new Set());
    }
  };

  useEffect(() => {
    if (selectAllCheckboxRef.current) {
      const numSelected = selectedQuestionIds.size;
      const numFiltered = filteredAndSortedQuestions.length;
      selectAllCheckboxRef.current.checked = numSelected === numFiltered && numFiltered > 0;
      selectAllCheckboxRef.current.indeterminate = numSelected > 0 && numSelected < numFiltered;
    }
  }, [selectedQuestionIds, filteredAndSortedQuestions]);

  const handleSelectByCategory = () => {
    const ids = allQuestions.filter(q => q.category === categoryFilter).map(q => q.id!);
    setSelectedQuestionIds(prev => new Set([...prev, ...ids]));
    showSuccessMessage(`${ids.length} Fragen nach Kategorie '${categoryFilter}' zur Auswahl hinzugefügt.`);
  };

  const handleSelectByVerband = () => {
    const ids = allQuestions.filter(q => q.verband === verbandFilter).map(q => q.id!);
    setSelectedQuestionIds(prev => new Set([...prev, ...ids]));
    showSuccessMessage(`${ids.length} Fragen nach Verband '${verbandFilter}' zur Auswahl hinzugefügt.`);
  };

  const handleSelectByType = () => {
    const ids = allQuestions.filter(q => formatQuestionType(q.type) === typeFilter).map(q => q.id!);
    setSelectedQuestionIds(prev => new Set([...prev, ...ids]));
    showSuccessMessage(`${ids.length} Fragen vom Typ '${typeFilter}' zur Auswahl hinzugefügt.`);
  };

  const getTypeBadgeClasses = (type: string) => {
    const baseClasses = "text-xs font-medium px-2.5 py-0.5 rounded-full";
    switch (type) {
      case 'Single':
        return `${baseClasses} bg-blue-100 text-[#0B79D0]`;
      case 'Multi':
        return `${baseClasses} bg-orange-100 text-orange-800`;
      default:
        return `${baseClasses} bg-gray-100 text-gray-800`;
    }
  };


  const SortIndicator = ({ columnKey }: { columnKey: SortableKeys }) => {
    if (sortConfig.key !== columnKey) return <span className="ml-1 text-gray-300">↕</span>;
    if (sortConfig.direction === 'asc') return <span className="ml-1 text-[#0B79D0]">▲</span>;
    return <span className="ml-1 text-[#0B79D0]">▼</span>;
  };

  return (
    <div className="w-full min-h-screen bg-slate-100">
      {/* Header */}
      <header className="bg-[#0B79D0] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Admin Dashboard</h1>
          <button onClick={onLogout} className="bg-white text-[#0B79D0] font-bold py-2 px-5 rounded-lg hover:bg-slate-100 transition-colors">
            Sign Out
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Import/Export Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl shadow-lg">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Import</h2>
            <p className="text-sm text-gray-600 mb-4">Laden Sie eine Datei (CSV, PDF, DOCX, etc.) hoch und wählen Sie den zugehörigen Verband.</p>
            <div className="flex items-center space-x-4">
              <input type="file" onChange={handleFileChange} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#0B79D0]/10 file:text-[#0B79D0] hover:file:bg-[#0B79D0]/20"/>
            </div>
             {file && (
              <div className="mt-4">
                <p className="text-sm font-medium text-gray-700 mb-2">Verband für Import auswählen:</p>
                <div className="flex gap-4">
                    {(['DZKB', 'ProHunde'] as const).map(v => (
                        <label key={v} className="flex items-center">
                            <input
                                type="radio"
                                name="uploadVerband"
                                value={v}
                                checked={uploadVerband === v}
                                onChange={() => setUploadVerband(v)}
                                className="h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"
                            />
                            <span className="ml-2 text-gray-700">{v}</span>
                        </label>
                    ))}
                </div>
              </div>
            )}
            {file && <button onClick={handleAnalyzeAndImport} disabled={analyzing || !uploadVerband} className="mt-4 w-full bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4] transition-colors disabled:bg-gray-400">
              {analyzing ? 'Analysiere...' : `"${file.name}" importieren`}
            </button>}
             {analyzing && <div className="mt-4 w-full">
                <div className="flex justify-between mb-1">
                    <span className="text-base font-medium text-slate-700">{analysisStatusMessage}</span>
                    <span className="text-sm font-medium text-[#0B79D0]">{analysisProgress}%</span>
                </div>
                <div className="w-full bg-slate-200 rounded-full h-2.5"><div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${analysisProgress}%` }}></div></div>
              </div>}
          </div>
          <div className="bg-white p-6 rounded-xl shadow-lg">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Daten Export</h2>
            <p className="text-sm text-gray-600 mb-4">Wählen Sie ein Format, um den aktuellen Fragenkatalog zu exportieren.</p>
            <div className="flex flex-col sm:flex-row gap-4 mt-8">
                <button onClick={handleExportCSV} className="flex-1 bg-slate-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-slate-700 transition-colors">
                CSV Export
                </button>
                <button onClick={handleExportPDF} className="flex-1 bg-orange-500 text-white font-bold py-2 px-5 rounded-lg hover:bg-orange-600 transition-colors">
                PDF Katalog
                </button>
            </div>
          </div>
        </div>

        {/* Question Management Table */}
        <div className="bg-white p-6 rounded-xl shadow-lg">
          <div className="flex flex-col md:flex-row justify-between items-start mb-4 gap-4">
            <h2 className="text-xl font-bold text-gray-800">Fragen verwalten ({filteredAndSortedQuestions.length})</h2>
            <div className="flex items-center gap-4 w-full md:w-auto flex-wrap justify-end">
              {selectedQuestionIds.size > 0 && (
                <button onClick={() => setIsBulkDeleteModalOpen(true)} className="bg-red-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-red-700 transition-colors whitespace-nowrap">
                  {selectedQuestionIds.size} Ausgewählte löschen
                </button>
              )}
              <button onClick={() => handleOpenEditModal()} className="bg-green-600 text-white font-bold py-2 px-4 rounded-lg hover:bg-green-700 transition-colors whitespace-nowrap">+ Neue Frage</button>
            </div>
          </div>

           {/* Filters and Selection Tools */}
          <div className="border-t border-b border-gray-200 py-4 mb-4">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  {/* Filters */}
                  <input type="text" placeholder="Suche..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="p-2 border rounded-lg w-full bg-white text-gray-900"/>
                  <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} className="p-2 border rounded-lg bg-white text-gray-900">
                    {categories.map(cat => <option key={cat} value={cat}>{cat === 'all' ? 'Alle Kategorien' : cat}</option>)}
                  </select>
                  <select value={verbandFilter} onChange={e => setVerbandFilter(e.target.value as 'all' | Verband)} className="p-2 border rounded-lg bg-white text-gray-900">
                      <option value="all">Alle Verbände</option>
                      <option value="DZKB">DZKB</option>
                      <option value="ProHunde">ProHunde</option>
                  </select>
                  <select value={typeFilter} onChange={e => setTypeFilter(e.target.value as 'all' | 'Single' | 'Multi')} className="p-2 border rounded-lg bg-white text-gray-900">
                      <option value="all">Alle Typen</option>
                      <option value="Single">Single</option>
                      <option value="Multi">Multi</option>
                  </select>
              </div>
              <div className="mt-4">
                  <h3 className="text-sm font-semibold text-gray-600 mb-2">Markierungs-Werkzeuge</h3>
                  <div className="flex flex-wrap gap-2">
                      <button onClick={handleSelectByCategory} disabled={categoryFilter === 'all'} className="text-sm bg-blue-100 text-blue-800 font-medium py-1 px-3 rounded-full disabled:bg-gray-100 disabled:text-gray-400 disabled:cursor-not-allowed">
                          Alle in Kategorie '{categoryFilter}' markieren
                      </button>
                      <button onClick={handleSelectByVerband} disabled={verbandFilter === 'all'} className="text-sm bg-blue-100 text-blue-800 font-medium py-1 px-3 rounded-full disabled:bg-gray-100 disabled:text-gray-400 disabled:cursor-not-allowed">
                          Alle in Verband '{verbandFilter}' markieren
                      </button>
                       <button onClick={handleSelectByType} disabled={typeFilter === 'all'} className="text-sm bg-blue-100 text-blue-800 font-medium py-1 px-3 rounded-full disabled:bg-gray-100 disabled:text-gray-400 disabled:cursor-not-allowed">
                          Alle vom Typ '{typeFilter}' markieren
                      </button>
                      {selectedQuestionIds.size > 0 && (
                        <button onClick={() => setSelectedQuestionIds(new Set())} className="text-sm bg-gray-200 text-gray-800 font-medium py-1 px-3 rounded-full">
                          Alle Markierungen aufheben
                        </button>
                      )}
                  </div>
              </div>
          </div>

          {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
          {successMessage && <p className="text-green-600 font-semibold mb-4">{successMessage}</p>}

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2 w-12">
                    <input
                      type="checkbox"
                      ref={selectAllCheckboxRef}
                      onChange={handleSelectAll}
                      className="h-4 w-4 rounded border-gray-300 text-[#0B79D0] focus:ring-[#0B79D0]"
                     />
                  </th>
                  <th className="p-2">Nr.</th>
                   <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('questionText')}>
                      <div className="flex items-center">Frage <SortIndicator columnKey="questionText" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('type')}>
                      <div className="flex items-center">Typ <SortIndicator columnKey="type" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('category')}>
                      <div className="flex items-center">Kategorie <SortIndicator columnKey="category" /></div>
                    </th>
                    <th className="p-2 cursor-pointer hover:bg-slate-100 select-none" onClick={() => requestSort('verband')}>
                      <div className="flex items-center">Verband <SortIndicator columnKey="verband" /></div>
                    </th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {isLoadingQuestions ? (<tr><td colSpan={7} className="text-center p-4">Lade Fragen...</td></tr>) 
                : filteredAndSortedQuestions.map((q, index) => {
                  const formattedType = formatQuestionType(q.type);
                  return (
                    <tr key={q.id} className={`border-b text-gray-800 ${selectedQuestionIds.has(q.id!) ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                      <td className="p-2">
                         <input
                            type="checkbox"
                            checked={selectedQuestionIds.has(q.id!)}
                            onChange={() => handleSelectOne(q.id!)}
                            className="h-4 w-4 rounded border-gray-300 text-[#0B79D0] focus:ring-[#0B79D0]"
                          />
                      </td>
                      <td className="p-2 text-center text-sm text-gray-500">{index + 1}</td>
                      <td className="p-2 max-w-md truncate">{q.questionText}</td>
                      <td className="p-2">
                        <span className={getTypeBadgeClasses(formattedType)}>
                          {formattedType}
                        </span>
                      </td>
                      <td className="p-2">{q.category || 'N/A'}</td>
                      <td className="p-2">{q.verband || 'N/A'}</td>
                      <td className="p-2 flex gap-4">
                        <button onClick={() => handleOpenEditModal(q)} className="text-[#0B79D0] font-semibold">Edit</button>
                        <button onClick={() => handleDeleteRequest(q)} className="text-red-500 font-semibold">Delete</button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {isEditModalOpen && editingQuestion && (
        <EditQuestionModal
          question={editingQuestion}
          isOpen={isEditModalOpen}
          onClose={handleCloseEditModal}
          onSave={handleSaveQuestion}
        />
      )}

      {questionToDelete && (
        <DeleteConfirmationModal
            isOpen={!!questionToDelete}
            onClose={() => setQuestionToDelete(null)}
            onConfirm={handleDeleteConfirmed}
            question={questionToDelete}
        />
      )}

      {isBulkDeleteModalOpen && (
        <BulkDeleteConfirmationModal
          isOpen={isBulkDeleteModalOpen}
          onClose={() => setIsBulkDeleteModalOpen(false)}
          onConfirm={handleBulkDeleteConfirmed}
          count={selectedQuestionIds.size}
        />
      )}
    </div>
  );
};


// Modal Component
interface EditQuestionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (question: Question) => void;
  question: Question;
}

const EditQuestionModal: React.FC<EditQuestionModalProps> = ({ isOpen, onClose, onSave, question }) => {
  const [editedQuestion, setEditedQuestion] = useState<Question>(question);

  useEffect(() => {
    setEditedQuestion(question);
  }, [question]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedQuestion(prev => ({...prev, [name]: value}));
  };

  const handleOptionChange = (index: number, value: string) => {
    const newOptions = [...editedQuestion.options];
    newOptions[index] = value;
    setEditedQuestion(prev => ({...prev, options: newOptions}));
  };

  const handleCorrectAnswerChange = (index: number) => {
    setEditedQuestion(prev => ({...prev, correctAnswerIndex: index}));
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-6 text-gray-800">{editedQuestion.id ? 'Frage bearbeiten' : 'Neue Frage erstellen'}</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700">Fragetext</label>
            <textarea name="questionText" value={editedQuestion.questionText} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900" rows={4}/>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">Kategorie</label>
              <input type="text" name="category" value={editedQuestion.category || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-gray-50 text-gray-900"/>
            </div>
             <div>
              <label className="block text-sm font-medium text-gray-700">Typ</label>
              <select name="type" value={editedQuestion.type || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                  <option value="Single">Single</option>
                  <option value="Multi">Multi</option>
              </select>
            </div>
             <div>
                <label className="block text-sm font-medium text-gray-700">Verband</label>
                <select name="verband" value={editedQuestion.verband || ''} onChange={handleTextChange} className="w-full p-2 border rounded mt-1 bg-white text-gray-900">
                    <option value="DZKB">DZKB</option>
                    <option value="ProHunde">ProHunde</option>
                </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Antworten (die erste ist A, die zweite B, usw.)</label>
            {editedQuestion.options.map((opt, index) => (
              <div key={index} className="flex items-center mt-2">
                <input type="radio" name="correctAnswer" checked={editedQuestion.correctAnswerIndex === index} onChange={() => handleCorrectAnswerChange(index)} className="mr-2 h-4 w-4 text-[#0B79D0] focus:ring-[#0B79D0]"/>
                <input type="text" value={opt} onChange={(e) => handleOptionChange(index, e.target.value)} className="w-full p-2 border rounded bg-gray-50 text-gray-900"/>
              </div>
            ))}
          </div>
        </div>
        <div className="flex justify-end gap-4 mt-8">
          <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">Abbrechen</button>
          <button onClick={() => onSave(editedQuestion)} className="bg-[#0B79D0] text-white font-bold py-2 px-5 rounded-lg hover:bg-[#0968b4]">Speichern</button>
        </div>
      </div>
    </div>
  );
};

interface DeleteConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    question: Question;
}

const DeleteConfirmationModal: React.FC<DeleteConfirmationModalProps> = ({ isOpen, onClose, onConfirm, question }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 text-gray-800">Löschen bestätigen</h2>
                <p className="text-gray-600 mb-6">Sind Sie sicher, dass Sie die folgende Frage endgültig löschen möchten?</p>
                <div className="bg-slate-50 border border-slate-200 p-4 rounded-lg mb-6">
                    <p className="font-semibold text-gray-700 truncate">{question.questionText}</p>
                </div>
                <div className="flex justify-end gap-4">
                    <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">
                        Abbrechen
                    </button>
                    <button onClick={onConfirm} className="bg-red-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-red-700">
                        Löschen
                    </button>
                </div>
            </div>
        </div>
    );
};

interface BulkDeleteConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => void;
    count: number;
}

const BulkDeleteConfirmationModal: React.FC<BulkDeleteConfirmationModalProps> = ({ isOpen, onClose, onConfirm, count }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50" onClick={onClose}>
            <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h2 className="text-2xl font-bold mb-4 text-gray-800">Löschen bestätigen</h2>
                <p className="text-gray-600 mb-6">Sind Sie sicher, dass Sie die <span className="font-bold">{count}</span> ausgewählten Fragen endgültig löschen möchten?</p>
                <div className="flex justify-end gap-4">
                    <button onClick={onClose} className="bg-slate-200 text-slate-700 font-bold py-2 px-5 rounded-lg hover:bg-slate-300">
                        Abbrechen
                    </button>
                    <button onClick={onConfirm} className="bg-red-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-red-700">
                        Löschen
                    </button>
                </div>
            </div>
        </div>
    );
};


export default AdminPanel;

import React, { useState, useCallback } from 'react';
import { Question } from './types';
import TopicSelector from './components/TopicSelector';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Loader from './components/Loader';
import Login from './components/Login';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';
import { generateQuiz } from './services/geminiService';
import { fetchRandomQuestions } from './services/supabaseService';

type GameState = 'config' | 'quiz' | 'results';
type View = 'user' | 'admin_login' | 'admin_panel';
export type QuizSource = 'ai' | 'db';
export type Verband = 'DZKB' | 'ProHunde';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [gameState, setGameState] = useState<GameState>('config');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<View>('user');

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleStartQuiz = useCallback(async (topic: string, numQuestions: number, source: QuizSource) => {
    setIsLoading(true);
    setError(null);
    try {
      let fetchedQuestions: Question[];
      // Der 'ai'-Pfad ist von der Benutzeroberfläche nicht mehr erreichbar, bleibt aber für eine mögliche zukünftige Verwendung erhalten.
      if (source === 'ai') {
        fetchedQuestions = await generateQuiz(topic, numQuestions);
      } else {
        fetchedQuestions = await fetchRandomQuestions(numQuestions);
      }

      // Mische die Antwortmöglichkeiten für jede Frage und aktualisiere den korrekten Index
      const questionsWithShuffledOptions = fetchedQuestions.map(question => {
        const correctAnswerText = question.options[question.correctAnswerIndex];

        // Fisher-Yates-Shuffle-Algorithmus für eine gute Zufälligkeit
        const shuffledOptions = [...question.options];
        for (let i = shuffledOptions.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [shuffledOptions[i], shuffledOptions[j]] = [shuffledOptions[j], shuffledOptions[i]];
        }

        const newCorrectAnswerIndex = shuffledOptions.findIndex(option => option === correctAnswerText);

        return {
          ...question,
          options: shuffledOptions,
          correctAnswerIndex: newCorrectAnswerIndex,
        };
      });


      setQuestions(questionsWithShuffledOptions);
      setUserAnswers(new Array(questionsWithShuffledOptions.length).fill(null));
      setGameState('quiz');
    } catch (err: any) {
      setError(err.message || 'Fehler beim Abrufen des Quiz. Bitte versuchen Sie es später erneut.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleAnswerSelect = (questionIndex: number, answerIndex: number) => {
    setUserAnswers(prev => {
      const newAnswers = [...prev];
      newAnswers[questionIndex] = answerIndex;
      return newAnswers;
    });
  };

  const handleSubmitQuiz = () => {
    setGameState('results');
  };

  const handleRestart = () => {
    setGameState('config');
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderUserContent = () => {
    if (isLoading) {
      return <Loader message="Quiz wird geladen... Bitte haben Sie einen Moment Geduld." />;
    }

    if (error) {
        return (
            <div className="text-center p-8 bg-white rounded-lg shadow-xl">
                <h2 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h2>
                <p className="text-slate-700 mb-6">{error}</p>
                <button
                    onClick={handleRestart}
                    className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors duration-300"
                >
                    Zurück zum Start
                </button>
            </div>
        );
    }

    switch (gameState) {
      case 'quiz':
        return <Quiz 
          questions={questions} 
          userAnswers={userAnswers} 
          onAnswerSelect={handleAnswerSelect} 
          onSubmit={handleSubmitQuiz} 
        />;
      case 'config':
      default:
        return <TopicSelector onStartQuiz={handleStartQuiz} />;
    }
  };

  if (view === 'admin_login') {
    return (
      <div className="min-h-screen font-sans flex items-center justify-center p-4 bg-gradient-to-b from-slate-800 to-slate-900">
        <AdminLogin onLoginSuccess={() => setView('admin_panel')} onCancel={() => setView('user')} />
      </div>
    );
  }

  if (view === 'admin_panel') {
     return (
      <div className="min-h-screen font-sans flex flex-col items-center p-4 bg-slate-100">
        <AdminPanel onLogout={() => setView('user')} />
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
       <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
        <Login onLoginSuccess={handleLoginSuccess} />
         <footer className="w-full max-w-4xl mx-auto text-center py-4 absolute bottom-0">
          <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors">
            Admin
          </button>
        </footer>
      </div>
    );
  }

  if (gameState === 'results') {
    return <Results 
      questions={questions} 
      userAnswers={userAnswers} 
      onRestart={handleRestart} 
    />;
  }

  return (
    <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
      <header className="w-full max-w-4xl mx-auto text-center mb-6">
        <h1 className="text-4xl md:text-5xl font-extrabold text-white drop-shadow-lg">DZKB Bayern e.V. Prüfungstrainer</h1>
        <p className="text-blue-100 mt-2 text-lg">Teste dein Wissen.</p>
      </header>
      <main className="w-full max-w-4xl mx-auto flex justify-center">
        {renderUserContent()}
      </main>
       <footer className="w-full max-w-4xl mx-auto text-center mt-8 text-blue-200 text-sm">
        <p>Unterstützt durch die Gemini API</p>
         <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors mt-2">
            Admin
          </button>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { Question } from '../types';
import CheckIcon from './icons/CheckIcon';
import XIcon from './icons/XIcon';

interface ResultsProps {
  questions: Question[];
  userAnswers: (number | null)[];
  onRestart: () => void;
}

const Results: React.FC<ResultsProps> = ({ questions, userAnswers, onRestart }) => {
  const score = userAnswers.reduce((acc, answer, index) => {
    return answer === questions[index].correctAnswerIndex ? acc + 1 : acc;
  }, 0);

  const scorePercentage = Math.round((score / questions.length) * 100);
  const PASSING_PERCENTAGE = 80; // Annahme: 80% zum Bestehen erforderlich
  const isPassed = scorePercentage >= PASSING_PERCENTAGE;

  return (
    <div className="fixed inset-0 bg-slate-900 font-sans overflow-y-auto">
      <div className="max-w-3xl mx-auto px-4 pt-8 pb-28">

        {/* Zusammenfassungs-Karte */}
        <div className={`bg-slate-800 rounded-xl p-6 mb-8 text-center relative overflow-hidden text-white`}>
           <div className={`absolute -top-4 -left-4 w-32 h-32 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>
           <div className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>

           <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center ${isPassed ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
             {isPassed 
               ? <CheckIcon className="w-10 h-10" /> 
               : <XIcon className="w-10 h-10" />}
           </div>
          <h2 className="text-2xl font-bold mt-4">{isPassed ? 'Bestanden' : 'Nicht bestanden'}</h2>
          <p className="text-5xl font-bold my-2 text-indigo-400">{scorePercentage}%</p>
          <p className="text-slate-400">{score} / {questions.length} richtig</p>
        </div>

        {/* Detailauswertung */}
        <h3 className="text-xl font-bold mb-4 text-slate-300">Detailauswertung</h3>
        <div className="space-y-4">
          {questions.map((question, index) => {
            const wasAnsweredCorrectly = userAnswers[index] === question.correctAnswerIndex;
            return (
              <div key={index} className="bg-white text-slate-800 rounded-xl p-5">
                <div className="flex items-start mb-4">
                  <span className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center mr-4 font-bold text-white ${wasAnsweredCorrectly ? 'bg-green-500' : 'bg-red-500'}`}>
                    {index + 1}
                  </span>
                  <p className="font-semibold text-lg">{question.questionText}</p>
                </div>

                <div className="space-y-3">
                  {question.options.map((option, optionIndex) => {
                    const isCorrect = optionIndex === question.correctAnswerIndex;
                    const isUserAnswer = userAnswers[index] === optionIndex;

                    let optionContainerClasses = "p-3 rounded-lg flex items-start border-2";
                    let optionTextClasses = "text-slate-800";
                    let subText: React.ReactNode | null = null;
                    let radioOrIcon: React.ReactNode;

                    if (isCorrect && isUserAnswer) {
                      optionContainerClasses += " bg-green-50 border-green-500";
                      optionTextClasses = "text-green-800 font-semibold";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIG GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-green-500 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-white" /></div>;
                    } else if (!isCorrect && isUserAnswer) {
                      optionContainerClasses += " bg-red-50 border-red-500";
                      optionTextClasses = "text-red-800 font-semibold";
                      subText = <span className="text-xs font-bold text-red-700 block mt-1">FALSCH GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-red-500 flex items-center justify-center mr-3 flex-shrink-0"><XIcon className="w-4 h-4 text-white" /></div>;
                    } else if (isCorrect && !isUserAnswer) {
                      optionContainerClasses += " bg-white border-dashed border-green-500";
                      optionTextClasses = "text-green-700";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIGE LÖSUNG</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-green-500" /></div>;
                    } else {
                      optionContainerClasses += " bg-white border-slate-300";
                      optionTextClasses = "text-slate-600";
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 mr-3 flex-shrink-0"></div>;
                    }

                    return (
                      <div key={optionIndex} className={optionContainerClasses}>
                        {radioOrIcon}
                        <div>
                          <span className={optionTextClasses}>{option}</span>
                          {subText}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Fixierte Footer-Buttons */}
      <div className="fixed bottom-0 left-0 right-0 bg-slate-900/80 backdrop-blur-sm border-t border-slate-700">
        <div className="max-w-3xl mx-auto p-4 flex justify-center items-center gap-4">
          <button onClick={onRestart} className="flex-1 bg-slate-700 text-white font-bold py-3 px-6 rounded-lg hover:bg-slate-600 transition-colors">Menü</button>
          <button onClick={onRestart} className="flex-1 bg-orange-500 text-white font-bold py-3 px-6 rounded-lg hover:bg-orange-600 transition-colors">Neuer Test</button>
        </div>
      </div>
    </div>
  );
};

export default Results;

