import { Question } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const DEFAULT_PROMPT_TEMPLATE = `Erstelle ein Multiple-Choice-Quiz auf Deutsch mit {numQuestions} Fragen zum Thema "{topic}". Jede Frage sollte 4 Antwortmöglichkeiten haben. Gib für jede Frage an, ob nur eine Antwort ('Single') oder mehrere Antworten ('Multi') korrekt sein können. Gib für jede Frage eine passende Kategorie an, die sich auf das Thema "{topic}" bezieht. Die Fragen sollten für Studenten geeignet sein, die sich auf eine Abschlussprüfung vorbereiten. Die Schwierigkeit sollte angemessen sein. Gib die Antwort ausschließlich im JSON-Format zurück, das dem bereitgestellten Schema entspricht, und stelle sicher, dass 'correctAnswerIndices' ein Array von Zahlen ist. Füge keine Markdown-Formatierung oder andere Texte außerhalb des JSON-Objekts hinzu.`;

const questionSchema = {
    type: Type.OBJECT,
    properties: {
      questionText: { type: Type.STRING },
      options: {
        type: Type.ARRAY,
        items: { type: Type.STRING },
        minItems: 4,
        maxItems: 4,
      },
      correctAnswerIndices: { 
        type: Type.ARRAY,
        items: { type: Type.INTEGER } 
      },
      category: { type: Type.STRING },
      type: { type: Type.STRING, enum: ['Single', 'Multi'] },
    },
    required: ['questionText', 'options', 'correctAnswerIndices', 'category', 'type'],
};

const responseSchema = {
    type: Type.ARRAY,
    items: questionSchema,
};

export const generateQuiz = async (topic: string, numQuestions: number): Promise<Question[]> => {
  const promptTemplate = localStorage.getItem('admin_prompt_template') || DEFAULT_PROMPT_TEMPLATE;
  const prompt = promptTemplate
    .replace('{numQuestions}', String(numQuestions))
    .replace('{topic}', topic);

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7,
      },
    });

    // FIX: Add a check for response.text to prevent crash on undefined.
    const jsonText = response.text?.trim();
    if (!jsonText) {
      throw new Error("API hat ein leeres oder ungültiges Quiz zurückgegeben.");
    }
    const quizData = JSON.parse(jsonText);

    if (!Array.isArray(quizData) || quizData.length === 0) {
        throw new Error("API hat ein leeres oder ungültiges Quiz zurückgegeben.");
    }

    return quizData as Question[];
  } catch (error) {
    console.error("Fehler bei der Gemini-API-Anfrage:", error);
    throw new Error("Die Quizfragen konnten nicht generiert werden.");
  }
};

const structureSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      category: { type: Type.STRING },
      content: { type: Type.STRING },
    },
    required: ['category', 'content'],
  },
};

export const structureAndExtractQuestions = async (
  textContent: string, 
  onProgress: (message: string) => void
): Promise<Omit<Question, 'explanation'>[]> => {

  // STEP 1: Structure the document
  onProgress('Struktur wird analysiert...');
  const structuringPrompt = `
    Analysiere das folgende Dokument. Identifiziere die Hauptabschnitte basierend auf Überschriften, Nummerierungen oder logischen thematischen Pausen.
    Gib für jeden identifizierten Abschnitt die Überschrift als 'category' und den dazugehörigen Text als 'content' zurück.
    Wenn keine klaren Überschriften vorhanden sind, aber der Text thematisch gruppiert erscheint, fasse ihn unter der Kategorie 'Allgemein' zusammen.
    Fasse den gesamten Inhalt des Dokuments in diesen Abschnitten zusammen. Gib das Ergebnis ausschließlich als JSON-Array zurück, das dem Schema entspricht.

    Dokumententext:
    ---
    ${textContent}
    ---
  `;

  let structuredData: { category: string; content: string }[];
  try {
    const structureResponse = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: structuringPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: structureSchema,
      },
    });
    // FIX: Add a check for structureResponse.text to prevent crash on undefined.
    const structureResponseText = structureResponse.text?.trim();
    if (!structureResponseText) {
      throw new Error("Konnte keine Struktur im Dokument erkennen.");
    }
    structuredData = JSON.parse(structureResponseText);
    if (!Array.isArray(structuredData) || structuredData.length === 0) {
      throw new Error("Konnte keine Struktur im Dokument erkennen.");
    }
  } catch (error) {
    console.error("Fehler bei der Strukturierungs-API:", error);
    throw new Error("Die Dokumentenstruktur konnte nicht analysiert werden. Überprüfen Sie das Dateiformat.");
  }

  // STEP 2: Extract questions from each structured part
  onProgress(`Extrahiere Fragen aus ${structuredData.length} Abschnitten...`);

  const extractionPromises = structuredData.map(async (section) => {
    const extractionPrompt = `
      Der folgende Text stammt aus der Kategorie '${section.category}'.
      Analysiere den Text und extrahiere daraus ALLE Quizfragen. Jede Frage muss einen Fragetext, vier Antwortmöglichkeiten, eine oder mehrere korrekte Antworten und einen Typ haben.
      - Die Kategorie für ALLE extrahierten Fragen aus diesem Text muss '${section.category}' sein.
      - Bestimme den Typ als 'Single', wenn nur eine Antwort richtig ist, oder 'Multi', wenn mehrere Antworten richtig sein könnten.
      - Die korrekte Antwort kann als Text oder Buchstabe (A, B, C, D) angegeben sein; wandle sie in ein Array von korrekten Indizes (beginnend bei 0) um.
      - Gib das Ergebnis ausschließlich im JSON-Format zurück, das dem Schema entspricht. Wenn keine Fragen im Text gefunden werden, gib ein leeres Array zurück.

      Text aus Kategorie '${section.category}':
      ---
      ${section.content}
      ---
    `;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: extractionPrompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: responseSchema,
        },
      });
      // FIX: Add a check for response.text to prevent crash on undefined.
      const responseText = response.text?.trim();
      if (!responseText) {
          return []; // Return empty array for this section if response is empty
      }
      const quizData = JSON.parse(responseText);
      // Ensure category is always set correctly, overriding any AI mistakes
      return (quizData as Question[]).map(q => ({ ...q, category: section.category }));
    } catch (error) {
      console.warn(`Fehler beim Extrahieren von Fragen aus der Kategorie '${section.category}':`, error);
      return []; // Return empty array for the failed section to not break the whole process
    }
  });

  const results = await Promise.all(extractionPromises);
  onProgress('Alle Abschnitte verarbeitet.');
  return results.flat(); // Flatten the array of arrays into a single array of questions
};

import React, { useState } from 'react';
import { Question } from '../types';

interface QuizProps {
  questions: Question[];
  userAnswers: number[][];
  onAnswerSelect: (questionIndex: number, answerIndex: number) => void;
  onSubmit: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, userAnswers, onAnswerSelect, onSubmit }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const currentQuestion = questions[currentQuestionIndex];
  const selectedAnswers = userAnswers[currentQuestionIndex] || [];

  return (
    <div className="bg-slate-50 p-6 md:p-8 rounded-xl shadow-md w-full">
      <div className="mb-6">
        <p className="text-sm text-gray-500">Frage {currentQuestionIndex + 1} von {questions.length}</p>
        <div className="w-full bg-slate-200 rounded-full h-2.5 mt-2">
          <div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}></div>
        </div>
      </div>

      <h2 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">{currentQuestion.questionText}</h2>
      {currentQuestion.type === 'Multi' && <p className="text-sm text-gray-500 mb-6">(Mehrere Antworten können richtig sein)</p>}


      <div className="space-y-4">
        {currentQuestion.options.map((option, index) => (
          <button
            key={index}
            onClick={() => onAnswerSelect(currentQuestionIndex, index)}
            className={`w-full text-left p-4 border-2 rounded-lg transition-all duration-200 text-gray-700 flex items-center
              ${selectedAnswers.includes(index)
                ? 'bg-blue-100 border-[#0B79D0] ring-2 ring-[#0B79D0]/50'
                : 'bg-white border-slate-300 hover:bg-slate-100 hover:border-[#0B79D0]'
              }`}
          >
            <div className="flex-shrink-0 w-6 h-6 flex items-center justify-center border-2 border-slate-400 rounded-md mr-4">
              {selectedAnswers.includes(index) && <div className="w-4 h-4 bg-[#0B79D0] rounded-sm"></div>}
            </div>
            <span className={`font-medium ${selectedAnswers.includes(index) ? 'text-[#0B79D0]' : 'text-gray-700'}`}>{option}</span>
          </button>
        ))}
      </div>

      <div className="mt-8 flex justify-between items-center">
        <button
          onClick={handlePrev}
          disabled={currentQuestionIndex === 0}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-6 rounded-lg hover:bg-slate-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Zurück
        </button>
        {currentQuestionIndex < questions.length - 1 ? (
          <button
            onClick={handleNext}
            className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
          >
            Weiter
          </button>
        ) : (
          <button
            onClick={onSubmit}
            className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
          >
            Abschicken
          </button>
        )}
      </div>
    </div>
  );
};

export default Quiz;

import React from 'react';
import { Question } from '../types';
import CheckIcon from './icons/CheckIcon';
import XIcon from './icons/XIcon';

interface ResultsProps {
  questions: Question[];
  userAnswers: number[][];
  onRestart: () => void;
}

const Results: React.FC<ResultsProps> = ({ questions, userAnswers, onRestart }) => {
  const score = userAnswers.reduce((acc, selectedIndices, index) => {
    const question = questions[index];
    const userSelection = selectedIndices || [];
    const correctAnswers = question.correctAnswerIndices || [];

    // Sort both arrays to compare them regardless of selection order
    const sortedUser = [...userSelection].sort();
    const sortedCorrect = [...correctAnswers].sort();

    const isIdentical = JSON.stringify(sortedUser) === JSON.stringify(sortedCorrect);

    return isIdentical ? acc + 1 : acc;
  }, 0);

  const scorePercentage = Math.round((score / questions.length) * 100);
  const PASSING_PERCENTAGE = 80; // Annahme: 80% zum Bestehen erforderlich
  const isPassed = scorePercentage >= PASSING_PERCENTAGE;

  return (
    <div className="fixed inset-0 bg-slate-900 font-sans overflow-y-auto">
      <div className="max-w-3xl mx-auto px-4 pt-8 pb-28">

        {/* Zusammenfassungs-Karte */}
        <div className={`bg-slate-800 rounded-xl p-6 mb-8 text-center relative overflow-hidden text-white`}>
           <div className={`absolute -top-4 -left-4 w-32 h-32 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>
           <div className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>

           <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center ${isPassed ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'}`}>
             {isPassed 
               ? <CheckIcon className="w-10 h-10" /> 
               : <XIcon className="w-10 h-10" />}
           </div>
          <h2 className="text-2xl font-bold mt-4">{isPassed ? 'Bestanden' : 'Nicht bestanden'}</h2>
          <p className="text-5xl font-bold my-2 text-indigo-400">{scorePercentage}%</p>
          <p className="text-slate-400">{score} / {questions.length} richtig</p>
        </div>

        {/* Detailauswertung */}
        <h3 className="text-xl font-bold mb-4 text-slate-300">Detailauswertung</h3>
        <div className="space-y-4">
          {questions.map((question, index) => {
            const userSelection = userAnswers[index] || [];
            const correctAnswers = question.correctAnswerIndices || [];
            const sortedUser = [...userSelection].sort();
            const sortedCorrect = [...correctAnswers].sort();
            const wasAnsweredCorrectly = JSON.stringify(sortedUser) === JSON.stringify(sortedCorrect);

            return (
              <div key={index} className="bg-white text-slate-800 rounded-xl p-5">
                <div className="flex items-start mb-4">
                  <span className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center mr-4 font-bold text-white ${wasAnsweredCorrectly ? 'bg-green-500' : 'bg-red-500'}`}>
                    {index + 1}
                  </span>
                  <p className="font-semibold text-lg">{question.questionText}</p>
                </div>

                <div className="space-y-3">
                  {question.options.map((option, optionIndex) => {
                    const isCorrectOption = question.correctAnswerIndices.includes(optionIndex);
                    const isUserSelection = userAnswers[index]?.includes(optionIndex);

                    let optionContainerClasses = "p-3 rounded-lg flex items-start border-2";
                    let optionTextClasses = "text-slate-800";
                    let subText: React.ReactNode | null = null;
                    let radioOrIcon: React.ReactNode;

                    if (isCorrectOption && isUserSelection) {
                      optionContainerClasses += " bg-green-50 border-green-500";
                      optionTextClasses = "text-green-800 font-semibold";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIG GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-green-500 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-white" /></div>;
                    } else if (!isCorrectOption && isUserSelection) {
                      optionContainerClasses += " bg-red-50 border-red-500";
                      optionTextClasses = "text-red-800 font-semibold";
                      subText = <span className="text-xs font-bold text-red-700 block mt-1">FALSCH GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-red-500 flex items-center justify-center mr-3 flex-shrink-0"><XIcon className="w-4 h-4 text-white" /></div>;
                    } else if (isCorrectOption && !isUserSelection) {
                      optionContainerClasses += " bg-white border-dashed border-green-500";
                      optionTextClasses = "text-green-700";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIGE LÖSUNG</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-green-500" /></div>;
                    } else {
                      optionContainerClasses += " bg-white border-slate-300";
                      optionTextClasses = "text-slate-600";
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 mr-3 flex-shrink-0"></div>;
                    }

                    return (
                      <div key={optionIndex} className={optionContainerClasses}>
                        {radioOrIcon}
                        <div>
                          <span className={optionTextClasses}>{option}</span>
                          {subText}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Fixierte Footer-Buttons */}
      <div className="fixed bottom-0 left-0 right-0 bg-slate-900/80 backdrop-blur-sm border-t border-slate-700">
        <div className="max-w-3xl mx-auto p-4 flex justify-center items-center gap-4">
          <button onClick={onRestart} className="flex-1 bg-slate-700 text-white font-bold py-3 px-6 rounded-lg hover:bg-slate-600 transition-colors">Menü</button>
          <button onClick={onRestart} className="flex-1 bg-orange-500 text-white font-bold py-3 px-6 rounded-lg hover:bg-orange-600 transition-colors">Neuer Test</button>
        </div>
      </div>
    </div>
  );
};

