        <div className={`bg-slate-800 rounded-xl p-6 mb-8 text-center relative overflow-hidden text-white`}>
           <div className={`absolute -top-4 -left-4 w-32 h-32 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>
           <div className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>

