import React, { useState, useCallback } from 'react';
import { Question } from './types';
import TopicSelector from './components/TopicSelector';
import Quiz from './components/Quiz';
import Results from './components/Results';
import Loader from './components/Loader';
import Login from './components/Login';
import AdminLogin from './components/AdminLogin';
import AdminPanel from './components/AdminPanel';
import { generateQuiz } from './services/geminiService';
import { fetchRandomQuestions } from './services/supabaseService';

type GameState = 'config' | 'quiz' | 'results';
type View = 'user' | 'admin_login' | 'admin_panel';
export type QuizSource = 'ai' | 'db';
export type Verband = 'DZKB' | 'ProHunde';

// Hilfsfunktion zur Normalisierung von Texten, um HTML-Entitäten und falsche Zeilenumbrüche zu korrigieren.
const normalizeText = (text: string | null | undefined): string => {
  if (!text) return '';
  let normalized = String(text);

  try {
      // Verwendet den DOM-Parser des Browsers, um HTML-Entitäten wie &amp;, &#x000D;, etc. zu dekodieren.
      const textarea = document.createElement("textarea");
      textarea.innerHTML = normalized;
      normalized = textarea.value;
  } catch (e) {
      console.warn('Textarea konnte nicht zum Dekodieren verwendet werden.', e);
  }

  // Entfernt alle verbleibenden HTML-Tags nach dem Dekodieren
  normalized = normalized.replace(/<[^>]*>?/gm, '');

  // Normalisiert verschiedene Zeilenumbruchformate in ein einziges \n
  normalized = normalized
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');

  // Ersetzt mehrere aufeinanderfolgende Zeilenumbrüche durch einen einzigen
  normalized = normalized.replace(/(\n\s*)+/g, '\n');

  return normalized.trim();
};


const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [gameState, setGameState] = useState<GameState>('config');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<number[][]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<View>('user');

  const handleLoginSuccess = () => {
    setIsAuthenticated(true);
  };

  const handleStartQuiz = useCallback(async (topic: string, numQuestions: number, source: QuizSource) => {
    setIsLoading(true);
    setError(null);
    try {
      let fetchedQuestions: Question[];
      // Der 'ai'-Pfad ist von der Benutzeroberfläche nicht mehr erreichbar, bleibt aber für eine mögliche zukünftige Verwendung erhalten.
      if (source === 'ai') {
        fetchedQuestions = await generateQuiz(topic, numQuestions);
      } else {
        fetchedQuestions = await fetchRandomQuestions(numQuestions);
      }

      // Normalisiere alle abgerufenen Fragen, um Text aus der Datenbank oder von der KI zu bereinigen
       const normalizedQuestions = fetchedQuestions.map(q => ({
        ...q,
        questionText: normalizeText(q.questionText),
        options: q.options.map(opt => normalizeText(opt)),
        category: normalizeText(q.category),
      }));

      // Mische die Antwortmöglichkeiten für jede Frage und aktualisiere den korrekten Index
      const questionsWithShuffledOptions = normalizedQuestions.map(question => {
        const correctAnswersText = question.correctAnswerIndices.map(i => question.options[i]);

        // Fisher-Yates-Shuffle-Algorithmus für eine gute Zufälligkeit
        const shuffledOptions = [...question.options];
        for (let i = shuffledOptions.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [shuffledOptions[i], shuffledOptions[j]] = [shuffledOptions[j], shuffledOptions[i]];
        }

        const newCorrectAnswerIndices = shuffledOptions
            .map((option, index) => (correctAnswersText.includes(option) ? index : -1))
            .filter(index => index !== -1)
            .sort((a, b) => a - b); // Sort for consistent order

        return {
          ...question,
          options: shuffledOptions,
          correctAnswerIndices: newCorrectAnswerIndices,
        };
      });


      setQuestions(questionsWithShuffledOptions);
      setUserAnswers(Array.from({ length: questionsWithShuffledOptions.length }, () => []));
      setGameState('quiz');
    } catch (err: any) {
      setError(err.message || 'Fehler beim Abrufen des Quiz. Bitte versuchen Sie es später erneut.');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleAnswerSelect = (questionIndex: number, answerIndex: number) => {
    const isMulti = questions[questionIndex].type === 'Multi';
    setUserAnswers(prev => {
      const newAnswers = [...prev];
      const currentSelection = newAnswers[questionIndex] || [];

      if (isMulti) {
        const newSelection = currentSelection.includes(answerIndex)
          ? currentSelection.filter(i => i !== answerIndex)
          : [...currentSelection, answerIndex].sort((a, b) => a - b);
        newAnswers[questionIndex] = newSelection;
      } else {
        newAnswers[questionIndex] = [answerIndex];
      }
      return newAnswers;
    });
  };

  const handleSubmitQuiz = () => {
    setGameState('results');
  };

  const handleRestart = () => {
    setGameState('config');
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderUserContent = () => {
    if (isLoading) {
      return <Loader message="Quiz wird geladen... Bitte haben Sie einen Moment Geduld." />;
    }

    if (error) {
        return (
            <div className="text-center p-8 bg-white rounded-lg shadow-xl">
                <h2 className="text-2xl font-bold text-red-600 mb-4">Ein Fehler ist aufgetreten</h2>
                <p className="text-slate-700 mb-6">{error}</p>
                <button
                    onClick={handleRestart}
                    className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors duration-300"
                >
                    Zurück zum Start
                </button>
            </div>
        );
    }

    switch (gameState) {
      case 'quiz':
        return <Quiz 
          questions={questions} 
          userAnswers={userAnswers} 
          onAnswerSelect={handleAnswerSelect} 
          onSubmit={handleSubmitQuiz} 
        />;
      case 'config':
      default:
        return <TopicSelector onStartQuiz={handleStartQuiz} />;
    }
  };

  if (view === 'admin_login') {
    return (
      <div className="min-h-screen font-sans flex items-center justify-center p-4 bg-gradient-to-b from-slate-800 to-slate-900">
        <AdminLogin onLoginSuccess={() => setView('admin_panel')} onCancel={() => setView('user')} />
      </div>
    );
  }

  if (view === 'admin_panel') {
     return (
      <div className="min-h-screen font-sans flex flex-col items-center p-4 bg-slate-100">
        <AdminPanel onLogout={() => setView('user')} />
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
       <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
        <Login onLoginSuccess={handleLoginSuccess} />
         <footer className="w-full max-w-4xl mx-auto text-center py-4 absolute bottom-0">
          <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors">
            Admin
          </button>
        </footer>
      </div>
    );
  }

  if (gameState === 'results') {
    return <Results 
      questions={questions} 
      userAnswers={userAnswers} 
      onRestart={handleRestart} 
    />;
  }

  return (
    <div className="min-h-screen font-sans flex flex-col items-center justify-center p-4 bg-gradient-to-b from-[#007bff] to-[#a0d2ff]">
      <header className="w-full max-w-4xl mx-auto text-center mb-6">
        <h1 className="text-4xl md:text-5xl font-extrabold text-white drop-shadow-lg">DZKB Bayern e.V. Prüfungstrainer</h1>
        <p className="text-blue-100 mt-2 text-lg">Teste dein Wissen.</p>
      </header>
      <main className="w-full max-w-4xl mx-auto flex justify-center">
        {renderUserContent()}
      </main>
       <footer className="w-full max-w-4xl mx-auto text-center mt-8 text-blue-200 text-sm">
        <p>Unterstützt durch die Gemini API</p>
         <button onClick={() => setView('admin_login')} className="text-blue-200 hover:text-white text-xs transition-colors mt-2">
            Admin
          </button>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Question } from '../types';

interface QuizProps {
  questions: Question[];
  userAnswers: number[][];
  onAnswerSelect: (questionIndex: number, answerIndex: number) => void;
  onSubmit: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, userAnswers, onAnswerSelect, onSubmit }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const currentQuestion = questions[currentQuestionIndex];
  const selectedAnswers = userAnswers[currentQuestionIndex] || [];

  const getTypeBadgeClasses = (type?: string | null): string => {
    const baseClasses = "text-xs font-medium px-2.5 py-0.5 rounded-full ml-3 align-middle";
    const formattedType = (type === 'Multi') ? 'Multi' : 'Single';

    switch (formattedType) {
      case 'Single':
        return `${baseClasses} bg-blue-100 text-[#0B79D0]`;
      case 'Multi':
        return `${baseClasses} bg-orange-100 text-orange-800`;
      default:
        return `${baseClasses} bg-gray-100 text-gray-800`;
    }
  };

  return (
    <div className="bg-slate-50 p-6 md:p-8 rounded-xl shadow-md w-full">
      <div className="mb-6">
        <p className="text-sm text-gray-500">Frage {currentQuestionIndex + 1} von {questions.length}</p>
        <div className="w-full bg-slate-200 rounded-full h-2.5 mt-2">
          <div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}></div>
        </div>
      </div>

      {/* Fragen-Navigationsleiste */}
      <div className="flex flex-wrap justify-center gap-2 mb-6 border-b pb-6 border-slate-200">
        {questions.map((_, index) => {
          const isAnswered = userAnswers[index] && userAnswers[index].length > 0;
          const isCurrent = index === currentQuestionIndex;

          let buttonClasses = "w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#0B79D0]";

          if (isCurrent) {
            buttonClasses += " bg-[#0B79D0] text-white";
          } else if (isAnswered) {
            buttonClasses += " bg-slate-300 text-slate-800 hover:bg-slate-400";
          } else {
            buttonClasses += " bg-slate-200 text-slate-600 hover:bg-slate-300";
          }

          return (
            <button
              key={index}
              onClick={() => setCurrentQuestionIndex(index)}
              className={buttonClasses}
              aria-label={`Gehe zu Frage ${index + 1}`}
            >
              {index + 1}
            </button>
          );
        })}
      </div>


      <div className="mb-6">
        <h2 className="text-xl md:text-2xl font-bold text-gray-800 inline whitespace-pre-wrap">{currentQuestion.questionText}</h2>
         <span className={getTypeBadgeClasses(currentQuestion.type)}>
            {currentQuestion.type === 'Multi' ? 'Multi' : 'Single'}
         </span>
      </div>


      <div className="space-y-4">
        {currentQuestion.options.map((option, index) => (
          <button
            key={index}
            onClick={() => onAnswerSelect(currentQuestionIndex, index)}
            className={`w-full text-left p-4 border-2 rounded-lg transition-all duration-200 text-gray-700 flex items-center
              ${selectedAnswers.includes(index)
                ? 'bg-blue-100 border-[#0B79D0] ring-2 ring-[#0B79D0]/50'
                : 'bg-white border-slate-300 hover:bg-slate-100 hover:border-[#0B79D0]'
              }`}
          >
            <div className="flex-shrink-0 w-6 h-6 flex items-center justify-center border-2 border-slate-400 rounded-md mr-4">
              {selectedAnswers.includes(index) && <div className="w-4 h-4 bg-[#0B79D0] rounded-sm"></div>}
            </div>
            <span className={`font-medium whitespace-pre-wrap ${selectedAnswers.includes(index) ? 'text-[#0B79D0]' : 'text-gray-700'}`}>{option}</span>
          </button>
        ))}
      </div>

      <div className="mt-8 flex justify-between items-center">
        <button
          onClick={handlePrev}
          disabled={currentQuestionIndex === 0}
          className="bg-slate-200 text-slate-700 font-bold py-2 px-6 rounded-lg hover:bg-slate-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          Zurück
        </button>
        {currentQuestionIndex < questions.length - 1 ? (
          <button
            onClick={handleNext}
            className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
          >
            Weiter
          </button>
        ) : (
          <button
            onClick={onSubmit}
            className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
          >
            Abschicken
          </button>
        )}
      </div>
    </div>
  );
};

export default Quiz;

import React from 'react';
import { Question } from '../types';
import CheckIcon from './icons/CheckIcon';
import XIcon from './icons/XIcon';

interface ResultsProps {
  questions: Question[];
  userAnswers: number[][];
  onRestart: () => void;
}

const Results: React.FC<ResultsProps> = ({ questions, userAnswers, onRestart }) => {
  const score = userAnswers.reduce((acc, selectedIndices, index) => {
    const question = questions[index];
    const userSelection = selectedIndices || [];
    const correctAnswers = question.correctAnswerIndices || [];

    // Sort both arrays to compare them regardless of selection order
    const sortedUser = [...userSelection].sort();
    const sortedCorrect = [...correctAnswers].sort();

    const isIdentical = JSON.stringify(sortedUser) === JSON.stringify(sortedCorrect);

    return isIdentical ? acc + 1 : acc;
  }, 0);

  const scorePercentage = Math.round((score / questions.length) * 100);
  const PASSING_PERCENTAGE = 80;
  const isPassed = scorePercentage >= PASSING_PERCENTAGE;

  return (
    <div className="fixed inset-0 bg-gradient-to-b from-[#007bff] to-[#a0d2ff] font-sans overflow-y-auto">
      <div className="max-w-3xl mx-auto px-4 pt-8 pb-28">

        {/* Zusammenfassungs-Karte */}
        <div className={`bg-white/80 backdrop-blur-sm rounded-xl p-6 mb-8 text-center relative overflow-hidden text-slate-800`}>
           <div className={`absolute -top-4 -left-4 w-32 h-32 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>
           <div className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-full ${isPassed ? 'bg-green-500' : 'bg-red-500'} opacity-10`}></div>

           <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center ${isPassed ? 'bg-green-500/20 text-green-500' : 'bg-red-500/20 text-red-500'}`}>
             {isPassed 
               ? <CheckIcon className="w-10 h-10" /> 
               : <XIcon className="w-10 h-10" />}
           </div>
          <h2 className="text-2xl font-bold mt-4">{isPassed ? 'Bestanden' : 'Nicht bestanden'}</h2>
          <p className="text-5xl font-bold my-2 text-[#0B79D0]">{scorePercentage}%</p>
          <p className="text-slate-600">{score} / {questions.length} richtig</p>
        </div>

        {/* Detailauswertung */}
        <h3 className="text-xl font-bold mb-4 text-white drop-shadow-md">Detailauswertung</h3>
        <div className="space-y-4">
          {questions.map((question, index) => {
            const userSelection = userAnswers[index] || [];
            const correctAnswers = question.correctAnswerIndices || [];
            const sortedUser = [...userSelection].sort();
            const sortedCorrect = [...correctAnswers].sort();
            const wasAnsweredCorrectly = JSON.stringify(sortedUser) === JSON.stringify(sortedCorrect);

            return (
              <div key={index} className="bg-white text-slate-800 rounded-xl p-5">
                <div className="flex items-start mb-4">
                  <span className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center mr-4 font-bold text-white ${wasAnsweredCorrectly ? 'bg-green-500' : 'bg-red-500'}`}>
                    {index + 1}
                  </span>
                  <p className="font-semibold text-lg whitespace-pre-wrap">{question.questionText}</p>
                </div>

                <div className="space-y-3">
                  {question.options.map((option, optionIndex) => {
                    const isCorrectOption = question.correctAnswerIndices.includes(optionIndex);
                    const isUserSelection = userAnswers[index]?.includes(optionIndex);

                    let optionContainerClasses = "p-3 rounded-lg flex items-start border-2";
                    let optionTextClasses = "text-slate-800";
                    let subText: React.ReactNode | null = null;
                    let radioOrIcon: React.ReactNode;

                    if (isCorrectOption && isUserSelection) {
                      optionContainerClasses += " bg-green-50 border-green-500";
                      optionTextClasses = "text-green-800 font-semibold";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIG GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-green-500 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-white" /></div>;
                    } else if (!isCorrectOption && isUserSelection) {
                      optionContainerClasses += " bg-red-50 border-red-500";
                      optionTextClasses = "text-red-800 font-semibold";
                      subText = <span className="text-xs font-bold text-red-700 block mt-1">FALSCH GEWÄHLT</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full bg-red-500 flex items-center justify-center mr-3 flex-shrink-0"><XIcon className="w-4 h-4 text-white" /></div>;
                    } else if (isCorrectOption && !isUserSelection) {
                      optionContainerClasses += " bg-white border-dashed border-green-500";
                      optionTextClasses = "text-green-700";
                      subText = <span className="text-xs font-bold text-green-700 block mt-1">RICHTIGE LÖSUNG</span>;
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 flex items-center justify-center mr-3 flex-shrink-0"><CheckIcon className="w-4 h-4 text-green-500" /></div>;
                    } else {
                      optionContainerClasses += " bg-white border-slate-300";
                      optionTextClasses = "text-slate-600";
                      radioOrIcon = <div className="w-6 h-6 rounded-full border-2 border-slate-400 mr-3 flex-shrink-0"></div>;
                    }

                    return (
                      <div key={optionIndex} className={optionContainerClasses}>
                        {radioOrIcon}
                        <div>
                          <span className={`${optionTextClasses} whitespace-pre-wrap`}>{option}</span>
                          {subText}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Fixierter Footer-Button */}
      <div className="fixed bottom-0 left-0 right-0 bg-white/50 backdrop-blur-sm border-t border-white/20">
        <div className="max-w-3xl mx-auto p-4">
          <button onClick={onRestart} className="w-full bg-orange-500 text-white font-bold py-3 px-6 rounded-lg hover:bg-orange-600 transition-colors">Neuer Test</button>
        </div>
      </div>
    </div>
  );
};

export default Results;

import React, { useState } from 'react';

// In einer echten Anwendung würde dies sicher gehandhabt, z.B. über Umgebungsvariablen.
const CORRECT_PASSWORD = 'dzkb-quiz-2024';

interface LoginProps {
  onLoginSuccess: () => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [password, setPassword] = useState('dzkb-quiz-2024');
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === CORRECT_PASSWORD) {
      setError(null);
      onLoginSuccess();
    } else {
      setError('Falsches Kennwort. Bitte versuchen Sie es erneut.');
      setPassword('');
    }
  };

  return (
    <div className="w-full max-w-sm bg-white p-8 rounded-2xl shadow-2xl text-center flex flex-col items-center animate-fade-in">
        <img 
          src="https://dzkb.bayern/wp-content/uploads/2024/09/Logo-DZKB-Hundefuehrerschein2024.jpg" 
          alt="DZKB Hundeführerschein Logo"
          className="w-64 h-auto mb-6"
        />
        <h1 className="text-3xl font-bold text-gray-800 tracking-wide">DZKB Bayern e.V.</h1>
        <p className="text-xl text-gray-600 mt-2">Theorie Test Prüfungen</p>

        <p className="text-gray-500 mt-8 mb-4">Bitte gib hier zum Starten dein Kennwort ein.</p>

        <form onSubmit={handleSubmit} className="w-full">
            <div className="space-y-4">
                <input 
                  type="password"
                  id="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full text-center text-lg font-medium text-gray-900 py-4 px-6 rounded-xl border-2 transition-all duration-300 ${
                    error 
                      ? 'border-red-400 bg-red-50 focus:ring-red-500/50' 
                      : 'bg-gray-100 border-gray-100 focus:outline-none focus:ring-2 focus:ring-[#0B79D0]/80 focus:border-transparent'
                  }`}
                  placeholder="Kennwort"
                  required
                  aria-describedby={error ? "password-error" : undefined}
                />
                <button
                  type="submit"
                  className="w-full bg-[#0B79D0] text-white font-bold py-4 px-4 rounded-xl shadow-lg hover:bg-[#0968b4] focus:outline-none focus:ring-4 focus:ring-[#0B79D0]/50 transition-all duration-300 transform hover:scale-105"
                >
                  Los geht's!
                </button>
            </div>
            {error && <p id="password-error" className="mt-3 text-sm text-red-600">{error}</p>}
        </form>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { QuizSource } from '../App';

interface TopicSelectorProps {
  onStartQuiz: (topic: string, numQuestions: number, source: QuizSource) => void;
}

const TOPIC = "DZKB Hundeführerschein Theorieprüfung";
const questionOptions = [5, 10, 20, 60];

const TopicSelector: React.FC<TopicSelectorProps> = ({ onStartQuiz }) => {
  const [numQuestions, setNumQuestions] = useState<number | null>(5);

  const handleStart = (source: QuizSource) => {
    if (numQuestions) {
      onStartQuiz(TOPIC, numQuestions, source);
    }
  };

  return (
    <div className="bg-slate-50 p-8 rounded-xl shadow-md animate-fade-in w-full max-w-2xl">
      <h2 className="text-3xl font-bold text-gray-800 text-center mb-2">Quiz-Modus auswählen</h2>
      <p className="text-gray-600 text-center mb-8">Wählen Sie die Anzahl der Fragen um zu starten.</p>

      <div className="space-y-8">
          <div>
            <h3 className="text-lg font-semibold text-center text-slate-700 mb-4">1. Anzahl der Fragen wählen</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {questionOptions.map((option) => (
                <button
                  type="button"
                  key={option}
                  onClick={() => setNumQuestions(option)}
                  className={`p-4 rounded-lg text-center font-bold text-lg transition-all duration-200 border-2 
                    ${numQuestions === option 
                      ? 'bg-[#0B79D0] text-white border-[#0B79D0] ring-4 ring-[#0B79D0]/30' 
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100 hover:border-slate-400'
                    }`}
                >
                  {option} Fragen
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-lg font-semibold text-center text-slate-700 mb-4">2. Quiz starten</h3>
            <div className="mt-4">
               <button
                type="button"
                onClick={() => handleStart('db')}
                className="w-full bg-[#0B79D0] text-white font-bold py-4 px-4 rounded-lg hover:bg-[#0968b4] focus:outline-none focus:ring-4 focus:ring-[#0B79D0]/50 transition-all duration-300 transform hover:scale-105 disabled:bg-gray-400 disabled:cursor-not-allowed disabled:scale-100"
                disabled={!numQuestions}
              >
                Quiz starten
              </button>
            </div>
          </div>
      </div>
    </div>
  );
};

export default TopicSelector;

