import { createClient } from '@supabase/supabase-js';
import { Question } from '../types';
import { SchulhundModuleType } from '../App';

// HINWEIS: Ersetzen Sie diese Platzhalter durch Ihre tatsächlichen Supabase-Anmeldeinformationen.
// Es wird dringend empfohlen, diese in einer .env-Datei zu speichern und process.env zu verwenden.
const SUPABASE_URL = 'https://prfvdhjbyhvpovusdlzk.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InByZnZkaGpieWh2cG92dXNkbHprIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzA5NzU1NzMsImV4cCI6MjA4NjU1MTU3M30.bW07S4k8t0J4Gr0R5Zbe3BZpEmNL0a_CSaZGfTMeaZY';
const IMAGE_BUCKET = 'question-images';


if (!SUPABASE_URL || !SUPABASE_KEY) {
  console.error("Supabase URL und Key sind nicht konfiguriert.");
}

const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

// Helper function to transform image paths to public URLs
const transformQuestionImageUrls = (questions: Question[]): Question[] => {
  return questions.map(q => {
    if (q.imageUrl) {
      const { data } = supabase.storage.from(IMAGE_BUCKET).getPublicUrl(q.imageUrl);
      return { ...q, imageUrl: data.publicUrl };
    }
    return q;
  });
};

/**
 * Speichert ein Array von Fragen in der Supabase-Datenbank.
 * @param questions Ein Array von Question-Objekten.
 */
export const saveQuestions = async (questions: Omit<Question, 'id' | 'created_at'>[]): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { error } = await supabase
    .from('questions')
    .insert(questions);

  if (error) {
    console.error('Fehler beim Speichern der Fragen in Supabase:', error);
    throw new Error('Fragen konnten nicht in der Datenbank gespeichert werden.');
  }
};


/**
 * Holt eine zufällige Anzahl von Fragen aus der Supabase-Datenbank.
 * @param count Die Anzahl der zufälligen Fragen, die abgerufen werden sollen.
 * @returns Ein Promise, das zu einem Array von Question-Objekten aufgelöst wird.
 */
export const fetchRandomQuestions = async (count: number, schulhundModule: SchulhundModuleType): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    let query = supabase
        .from('questions')
        .select('*');

    if (schulhundModule === 'hundefuehrerschein') {
      // Schließe die spezielle Kategorie aus
      query = query.not('category', 'eq', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    } else if (schulhundModule === 'schulhund') {
      // Wähle NUR die spezielle Kategorie aus
      query = query.eq('category', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    }

    const { data, error } = await query;

    if (error) {
        console.error('Fehler beim Abrufen der Fragen aus Supabase:', error);
        throw new Error('Fragen konnten nicht aus der Datenbank geladen werden.');
    }

    if (!data || data.length === 0) {
        throw new Error(`Keine Fragen in der Datenbank gefunden, die den Kriterien entsprechen.`);
    }

    // Mische das Array und wähle die ersten 'count' Elemente aus.
    const shuffled = data.sort(() => 0.5 - Math.random());
    const selectedQuestions = shuffled.slice(0, count) as Question[];
    return transformQuestionImageUrls(selectedQuestions);
};

/**
 * Holt alle Fragen aus der Datenbank.
 */
export const fetchAllQuestions = async (): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .order('id', { ascending: true });

    if (error) {
        console.error('Fehler beim Abrufen aller Fragen:', error);
        throw new Error('Fragen konnten nicht geladen werden.');
    }
    return transformQuestionImageUrls(data as Question[]);
};

/**
 * Erstellt eine neue Frage in der Datenbank.
 */
export const createQuestion = async (question: Omit<Question, 'id' | 'created_at'>): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .insert([question])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen der Frage:', error);
        throw new Error('Frage konnte nicht erstellt werden.');
    }
    const [transformedQuestion] = transformQuestionImageUrls([data as Question]);
    return transformedQuestion;
};


/**
 * Aktualisiert eine bestehende Frage in der Datenbank.
 */
export const updateQuestion = async (question: Question): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (!question.id) throw new Error("Frage benötigt eine ID zum Aktualisieren.");

    const { id, created_at, ...updateData } = question;

    // If the imageUrl is a full URL, it means it hasn't been changed. We need to store only the path.
    if (updateData.imageUrl && updateData.imageUrl.includes(IMAGE_BUCKET)) {
        // Extract path from the full public URL
        const urlParts = updateData.imageUrl.split('/');
        updateData.imageUrl = urlParts.slice(urlParts.indexOf(IMAGE_BUCKET) + 1).join('/');
    }

    const { data, error } = await supabase
        .from('questions')
        .update(updateData)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren der Frage:', error);
        throw new Error('Frage konnte nicht aktualisiert werden.');
    }
    const [transformedQuestion] = transformQuestionImageUrls([data as Question]);
    return transformedQuestion;
};

/**
 * Löscht eine Frage aus der Datenbank und das zugehörige Bild aus dem Speicher.
 */
export const deleteQuestion = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    // 1. Get the image path before deleting the question record
    const { data: questionData, error: fetchError } = await supabase
        .from('questions')
        .select('imageUrl')
        .eq('id', id)
        .single();

    if (fetchError) {
        console.error('Fehler beim Abrufen der Frage vor dem Löschen:', fetchError);
        throw new Error('Frage konnte nicht gefunden werden, um sie zu löschen.');
    }

    // 2. Delete the question record from the database
    const { error: deleteError } = await supabase
        .from('questions')
        .delete()
        .eq('id', id);

    if (deleteError) {
        console.error('Fehler beim Löschen der Frage:', deleteError);
        throw new Error('Frage konnte nicht gelöscht werden.');
    }

    // 3. If an image path exists, delete the image from storage
    if (questionData.imageUrl) {
        await deleteImage(questionData.imageUrl);
    }
};

/**
 * Löscht mehrere Fragen auf einmal und die zugehörigen Bilder aus dem Speicher.
 */
export const deleteMultipleQuestions = async (ids: number[]): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (ids.length === 0) return;

    // 1. Get image paths for all questions to be deleted
    const { data: questionsData, error: fetchError } = await supabase
        .from('questions')
        .select('imageUrl')
        .in('id', ids);

    if (fetchError) {
        console.error('Fehler beim Abrufen der Fragen vor dem Massenlöschen:', fetchError);
        throw new Error('Fragen konnten nicht gefunden werden.');
    }

    // 2. Delete the question records from the database
    const { error: deleteError } = await supabase
        .from('questions')
        .delete()
        .in('id', ids);

    if (deleteError) {
        console.error('Fehler beim Löschen mehrerer Fragen:', deleteError);
        throw new Error('Die ausgewählten Fragen konnten nicht gelöscht werden.');
    }

    // 3. Collect all valid image paths and delete them from storage
    const imagePathsToDelete = questionsData
        .map(q => q.imageUrl)
        .filter((path): path is string => !!path);

    if (imagePathsToDelete.length > 0) {
        await supabase.storage.from(IMAGE_BUCKET).remove(imagePathsToDelete);
    }
};

/**
 * Lädt ein Bild in den Supabase Storage hoch.
 * @param file Die Bilddatei, die hochgeladen werden soll.
 * @returns Der Pfad zum hochgeladenen Bild.
 */
export const uploadImage = async (file: File): Promise<string> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const filePath = `${Date.now()}-${file.name.replace(/\s/g, '_')}`;
    const { data, error } = await supabase.storage
        .from(IMAGE_BUCKET)
        .upload(filePath, file);

    if (error) {
        console.error('Fehler beim Hochladen des Bildes:', error);
        throw new Error('Bild konnte nicht hochgeladen werden.');
    }

    return data.path;
};


/**
 * Löscht ein Bild aus dem Supabase Storage.
 * @param path Der Pfad zum Bild, das gelöscht werden soll.
 */
export const deleteImage = async (path: string): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    // If the path is a full URL, extract the path part
    let imagePath = path;
    if (path.includes(IMAGE_BUCKET)) {
        const urlParts = path.split('/');
        imagePath = urlParts.slice(urlParts.indexOf(IMAGE_BUCKET) + 1).join('/');
    }

    const { error } = await supabase.storage
        .from(IMAGE_BUCKET)
        .remove([imagePath]);

    if (error) {
        console.error('Fehler beim Löschen des Bildes:', error);
        // Don't throw an error, just log it, as the main operation (e.g., question deletion) might have succeeded.
    }
};

